```java
// SafeFramingProxy.java —— 前置代理: 表面透传 CL/TE 危险分帧头, 实为三重走私防护
public class SafeFramingProxy {

    private static final URI PRIVATE_ORIGIN = URI.create("http://10.8.0.1:8080");

    public void handle(HttpServletRequest req, HttpServletResponse resp) throws Exception {
        String te = req.getHeader("Transfer-Encoding");
        String cl = req.getHeader("Content-Length");

        // 防线1: 显式固定解析顺序 —— CL 与 TE 并存即整体 400, 不做任何择一启发式
        if (te != null && cl != null) {
            resp.sendError(400, "ambiguous framing rejected");
            return;
        }
        // 仅放行标准 chunked, 其余传输编码一律拒绝
        if (te != null && !"chunked".equalsIgnoreCase(te.trim())) {
            resp.sendError(400, "unsupported transfer-coding");
            return;
        }

        // 防线2: 缓存键纳入全部影响分帧语义的头, 同键必同帧, 杜绝缓存投毒
        String cacheKey = req.getMethod() + req.getRequestURI() + "|te=" + te + "|cl=" + cl;

        // 防线3: 私有源锁定 —— 丢弃入站 Host/X-Forwarded-*, 仅发往固定内网源
        HttpRequest outbound = HttpRequest.newBuilder(PRIVATE_ORIGIN.resolve(req.getRequestURI()))
                .header("Host", PRIVATE_ORIGIN.getHost())
                .header("X-Framing-Mode", te != null ? "CHUNKED" : "CONTENT_LENGTH")
                .build();
        HttpResponse<byte[]> upstream = HttpClient.newHttpClient()
                .send(outbound, HttpResponse.BodyHandlers.ofByteArray());

        // 哈希校验: 回源体与后端随附 SHA-256 摘要恒等比较, 不符即 502 且不落缓存
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(upstream.body());
        String claimed = upstream.headers().firstValue("X-Body-Sha256").orElse("");
        if (claimed.length() != 64 || !MessageDigest.isEqual(digest, HexFormat.of().parseHex(claimed))) {
            resp.sendError(502, "integrity check failed");
            return;
        }
        CacheStore.put(cacheKey, upstream.body(), digest);
        resp.getOutputStream().write(upstream.body());
    }
}
