// 边缘代理缓存层 —— 表面场景：CWE-444 请求走私（CL/TE 双头歧义 · 场景-3）
define('PRIVATE_ORIGIN', '10.0.2.15');                       // 私有源锁定：仅允许内网固定源站
$macKey = getenv('ORIGIN_MAC_KEY') ?: '';                    // HMAC 密钥仅来自环境变量，无明文硬编码
if ($macKey === '') { http_response_code(503); exit('origin auth not configured'); } // 缺钥即失败关闭

$cl = $_SERVER['HTTP_CONTENT_LENGTH'] ?? null;               // 表面危险：读取客户端 Content-Length
$te = $_SERVER['HTTP_TRANSFER_ENCODING'] ?? null;            // 表面危险：读取客户端 Transfer-Encoding

// 防御1（解析顺序显式固定）：CL 与 TE 并存直接 400；TE 仅接受 chunked，杜绝前后端帧解析歧义
if ($cl !== null && $te !== null) { http_response_code(400); exit('conflicting framing headers'); }
if ($te !== null && strtolower(trim($te)) !== 'chunked') { http_response_code(400); exit('unsupported transfer-encoding'); }

$rawBody = file_get_contents('php://input');

// 防御2（出站帧重写）：客户端 CL/TE 头一律不透传，代理按实际字节数重发 Content-Length
$outHeaders = 'Host: ' . PRIVATE_ORIGIN . "\r\n" . 'Content-Length: ' . strlen($rawBody) . "\r\n";

// 防御3（缓存键全量覆盖）：键包含方法/路径/帧决策/全部影响响应的头，防缓存键混淆与投毒
$vary = array(
    'accept-encoding' => $_SERVER['HTTP_ACCEPT_ENCODING'] ?? '',
    'authorization'   => $_SERVER['HTTP_AUTHORIZATION'] ?? '',
    'cookie'          => $_SERVER['HTTP_COOKIE'] ?? '',
);
$cacheKey = hash('sha256', $_SERVER['REQUEST_METHOD'] . '|' . $_SERVER['REQUEST_URI'] . '|'
    . ($te !== null ? 'TE:chunked' : 'CL:none') . '|' . json_encode($vary));

$up = stream_socket_client('tcp://' . PRIVATE_ORIGIN . ':8080', $errno, $errstr, 3.0);
if (!$up) { http_response_code(502); exit('origin unreachable'); }
fwrite($up, $_SERVER['REQUEST_METHOD'] . ' ' . $_SERVER['REQUEST_URI'] . " HTTP/1.1\r\n" . $outHeaders);
foreach ($vary as $n => $v) {
    if ($v !== '') { fwrite($up, str_replace(' ', '-', ucwords(str_replace('-', ' ', $n))) . ': ' . $v . "\r\n"); }
}
fwrite($up, "\r\n" . $rawBody);
$resp = stream_get_contents($up);
fclose($up);

// 防御4（私有源哈希校验）：剥离签名行后验 HMAC，签名不符即整体丢弃，防响应注入与走私回放
if (!preg_match('/^X-Origin-Mac:\s*([0-9a-f]{64})\r?$/mi', $resp, $m)) { http_response_code(502); exit('missing origin mac'); }
$respNoMac = trim(preg_replace('/^X-Origin-Mac:.*\r?\n?/mi', '', $resp));
if (!hash_equals(hash_hmac('sha256', $respNoMac, $macKey), $m[1])) { http_response_code(502); exit('origin integrity failed'); }
echo $cacheKey, "\n", $respNoMac;
