import hashlib
import hmac

ORIGIN_IP = "10.0.0.5"                     # 私有源锁定：唯一允许的上游地址
ORIGIN_HOST = "internal.api.local"
PSK = b"local-demo-bind-key"               # 演示用绑定常量，非真实凭据

def resolve_framing(headers):
    """显式固定解析顺序：先 TE 后 CL，任何歧义帧直接拒绝。"""
    te = headers.get("Transfer-Encoding")
    cl = headers.get("Content-Length")
    if te is not None and cl is not None:
        return None                        # CL+TE 同现：走私向量，拒绝
    if te is not None:
        if te.strip().lower() != "chunked" or "," in te:
            return None                    # TE 混淆（TE-TE）拒绝
        return ("chunked", None)
    if cl is not None:
        if "," in cl or len(cl.split()) != 1 or not cl.strip().isdigit():
            return None                    # 重复/多值/非数字 CL（CL-CL）拒绝
        return ("identity", int(cl))
    return ("identity", 0)

def cache_key(method, path, headers):
    """缓存键包含全部影响头，杜绝键差异导致的缓存投毒。"""
    infl = ["Transfer-Encoding", "Content-Length", "Cookie", "X-Forwarded-For"]
    canon = "\n".join([method, path] + [headers.get(h, "-") for h in infl])
    return hashlib.sha256(canon.encode()).hexdigest()

def handle(method, path, headers, body, send_to_origin):
    if headers.get("Host") != ORIGIN_HOST:
        return 403, "host not pinned"
    framing = resolve_framing(headers)
    if framing is None:
        return 400, "ambiguous framing rejected"
    canon = method + "\n" + path + "\n" + str(framing) + "\n" + (body or "")
    digest = hmac.new(PSK, canon.encode(), hashlib.sha256).hexdigest()
    resp = send_to_origin(ORIGIN_IP, digest, method, path, framing, body)
    if not hmac.compare_digest(resp.get("digest", ""), digest):
        return 502, "origin digest mismatch"
    return 200, cache_key(method, path, headers) + ":" + resp["payload"]
