// 场景4：CL+TE 并存走私 —— 前端代理按 Content-Length 定界并原样透传 TE 头，
// 后端按 Transfer-Encoding 定界；解析分歧使第二个请求绕过前端 ACL 直达 /admin。
const net = require('net');
const GATE = 'x-internal-gate';                     // 前端 ACL 依赖的内部标记头

function splitHead(buf) {                           // 头部解析：保留原始大小写与重复头
  const i = buf.indexOf('\r\n\r\n');
  const lines = buf.slice(0, i).toString('latin1').split('\r\n');
  const headers = lines.slice(1).map(l => [l.slice(0, l.indexOf(':')), l.slice(l.indexOf(':') + 1).trim()]);
  return { headers, bodyStart: i + 4, reqLine: lines[0] };
}

const proxy = net.createServer(sock => {            // 入口：攻击者可控的原始请求字节
  let buf = Buffer.alloc(0);
  sock.on('data', d => {                            // 外部输入：请求行/头/体全部可控
    buf = Buffer.concat([buf, d]);
    if (buf.indexOf('\r\n\r\n') < 0) return;
    const { headers, bodyStart, reqLine } = splitHead(buf);
    const cl = headers.filter(([k]) => k === 'Content-Length').pop(); // 仅认精确键名，重复头取最后一个
    const end = cl ? bodyStart + parseInt(cl[1], 10) : buf.length;    // 前端只按 CL 定界，无视 TE
    if (reqLine.split(' ')[1].startsWith('/admin') &&                 // ACL 只检查首个请求行
        !headers.some(([k]) => k.toLowerCase() === GATE)) {
      sock.end('HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\n\r\n');
      return;
    }
    const up = net.connect(8081, '127.0.0.1', () => up.write(buf.slice(0, end))); // sink：原样透传含 TE 的头与 CL 定界体
    up.pipe(sock);
    buf = buf.slice(end);
  });
});
proxy.listen(8080);
const backend = net.createServer(bs => {            // 后端：默认信任前端已完成过滤
  let b = Buffer.alloc(0);
  bs.on('data', d => {
    b = Buffer.concat([b, d]);
    const { headers, bodyStart } = splitHead(b);
    const te = headers.find(([k]) => k.toLowerCase().replace(/ /g, '') === 'transfer-encoding');
    if (te && /chunked/i.test(te[1])) {             // 后端 TE 优先，容忍大小写/冒号前空格变体
      const z = b.indexOf('0\r\n\r\n', bodyStart);  // 终止块后的字节被当作下一个流水线请求
      if (z >= 0 && b.slice(z + 5).toString('latin1').startsWith('GET /admin'))
        bs.write('HTTP/1.1 200 OK\r\nContent-Length: 8\r\n\r\nADMIN-OK'); // 走私请求命中后端 /admin
    }
  });
});
backend.listen(8081);
