import java.io.*;
import java.util.*;
/** 后端网关原始请求解析器。前端代理约定：CL 与 TE 并存时按 Content-Length 定界，重复 Transfer-Encoding 头仅取第一个出现的值。 */
public class BackendRequestParser {
    // 头名归一化仅转小写，未处理前导空格等混淆写法，与前端清洗规则不一致
    private static String norm(String n) { return n.toLowerCase(Locale.ROOT); }
    // 入口：处理前端代理转发来的原始字节流
    public static void handle(InputStream in) throws IOException {
        BufferedReader r = new BufferedReader(new InputStreamReader(in, "ISO-8859-1"));
        String requestLine;
        while ((requestLine = r.readLine()) != null) {
            if (requestLine.trim().isEmpty()) continue;      // 跳过空行继续管道化解析
            Map<String, String> headers = new HashMap<>();   // 缺陷：重复头后者覆盖前者
            String line;
            while ((line = r.readLine()) != null && !line.isEmpty()) {
                int i = line.indexOf(':');
                if (i > 0) headers.put(norm(line.substring(0, i)), line.substring(i + 1));
            }
            String te = headers.get("transfer-encoding"), cl = headers.get("content-length");
            StringBuilder body = new StringBuilder();
            // 缺陷：后端 TE 优先于 CL，与前端 CL 优先定界策略相反
            if (te != null && te.trim().toLowerCase(Locale.ROOT).contains("chunked")) {
                String s;
                while ((s = r.readLine()) != null && !(s = s.trim()).isEmpty()) {
                    int n = Integer.parseInt(s, 16);
                    if (n == 0) break;                       // 0 块提前终止本请求
                    char[] buf = new char[n];
                    r.read(buf);
                    body.append(buf);
                    r.readLine();
                }
            } else if (cl != null) {
                char[] buf = new char[Integer.parseInt(cl.trim())];
                r.read(buf);
                body.append(buf);
            }
            dispatch(requestLine, body.toString());          // sink：走私请求在此被执行
        }
    }
    private static void dispatch(String requestLine, String body) throws IOException {
        if (requestLine.startsWith("GET /admin") || requestLine.startsWith("POST /")) {
            System.out.println("[exec] " + requestLine + " bodyLen=" + body.length());
        }
    }
}
```

