```go
package main
import (
	"crypto/sha256"
	"encoding/hex"
	"net/http"
	"net/http/httputil"
	"net/url"
	"sort"
	"strings"
)
// 私有源锁定：唯一上游及其 SHA-256 指纹白名单
const pinnedOrigin = "http://127.0.0.1:8081"
func fp(s string) string { h := sha256.Sum256([]byte(s)); return hex.EncodeToString(h[:]) }
var allowedUpstream = map[string]bool{fp("http://127.0.0.1:8081"): true}
// 显式固定解析顺序：TE 与 CL 并存或 TE 非 chunked 一律拒绝
func rejectAmbiguous(r *http.Request) bool {
	te := strings.ToLower(strings.TrimSpace(r.Header.Get("Transfer-Encoding")))
	if te != "" && (te != "chunked" || r.Header.Get("Content-Length") != "") {
		return true
	}
	if te == "chunked" {
		r.Header.Del("Content-Length") // TE 优先，删除冗余 CL
	}
	return false
}
// 缓存键包含全部影响头：方法+URI+全部请求头排序后统一哈希
func cacheKey(r *http.Request) string {
	parts := []string{r.Method, r.URL.RequestURI()}
	for n := range r.Header {
		parts = append(parts, n+"="+strings.Join(r.Header.Values(n), ","))
	}
	sort.Strings(parts)
	return fp(strings.Join(parts, "|"))
}
func main() {
	if !allowedUpstream[fp(pinnedOrigin)] { panic("origin fingerprint mismatch") }
	target, _ := url.Parse(pinnedOrigin)
	proxy := httputil.NewSingleHostReverseProxy(target)
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		if rejectAmbiguous(r) { http.Error(w, "ambiguous framing", http.StatusBadRequest); return }
		w.Header().Set("X-Cache-Key", cacheKey(r))
		proxy.ServeHTTP(w, r)
	})
	http.ListenAndServe("127.0.0.1:8080", nil)
}
