const http = require('http');
const crypto = require('crypto');

const PINNED_HOST = '10.0.0.5:8080'; // 私有源锁定:唯一允许的上游虚拟主机
const PINNED_HOST_HASH = crypto.createHash('sha256').update(PINNED_HOST).digest('hex');

// 防线1:显式固定解析顺序,帧定界头必须恰好存在一个
function framingOf(rawHeaders) {
  const names = rawHeaders.map(h => h.split(':')[0].trim().toLowerCase());
  const cl = names.filter(n => n === 'content-length').length;
  const te = names.filter(n => n === 'transfer-encoding').length;
  return cl + te === 1 ? (cl === 1 ? 'content-length' : 'transfer-encoding') : null;
}

const cache = new Map();

http.createServer((req, res) => {
  if (framingOf(req.rawHeaders) === null) {
    res.writeHead(400); res.end('ambiguous framing'); return;
  }
  if (!req.url.startsWith('/')) {
    res.writeHead(400); res.end('bad target'); return;
  }
  const gotHash = crypto.createHash('sha256').update(String(req.headers.host)).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(PINNED_HOST_HASH), Buffer.from(gotHash))) {
    res.writeHead(421); res.end('host pin mismatch'); return;
  }
  // 防线2:缓存键包含全部影响响应的头
  const parts = [req.method, req.url];
  for (const h of ['accept-encoding', 'cookie', 'authorization', 'x-forwarded-host', 'user-agent']) {
    parts.push(h + '=' + String(req.headers[h]));
  }
  const cacheKey = crypto.createHash('sha256').update(parts.join('|')).digest('hex');
  if (cache.has(cacheKey)) { res.writeHead(200); res.end(cache.get(cacheKey)); return; }
  const upstream = http.request({ host: '10.0.0.5', port: 8080, method: req.method, path: req.url,
    headers: { host: PINNED_HOST } }, up => {
    let body = '';
    up.on('data', d => { body += d; });
    up.on('end', () => { cache.set(cacheKey, body); res.writeHead(up.statusCode); res.end(body); });
  });
  req.pipe(upstream);
}).listen(8080);
