import hashlib, hmac

ORIGIN_HOST = "10.0.12.7"                          # 私有源站锁定（仅内网可达）
_SIGN_KEY = b"demo-only-signing-key-not-real"      # 演示签名密钥，非真实凭据

def canonical_framing(headers):
    """显式固定解析顺序：CL/TE 并存、重复或取值歧义一律拒绝，输出唯一帧模式"""
    cls = [str(v).strip() for v in headers.get("Content-Length", [])]
    tes = [str(v).strip().lower() for v in headers.get("Transfer-Encoding", [])]
    if (cls and tes) or len(cls) > 1 or len(tes) > 1:
        return None
    if tes and tes[0] != "chunked":
        return None
    return ("TE", "chunked") if tes else ("CL", (cls[0] if cls else "0"))

def cache_key(method, path, headers, framing):
    """缓存键包含全部影响头：方法/路径/Host/协议/帧模式"""
    material = "|".join([method, path,
                         (headers.get("Host") or [""])[0],
                         (headers.get("X-Forwarded-Proto") or ["http"])[0],
                         framing[0], framing[1]])
    return hashlib.sha256(material.encode()).hexdigest()

def forward(method, path, headers, body):
    framing = canonical_framing(headers)
    if framing is None:
        return 400, "ambiguous framing rejected"
    if headers.get("Host", []) != [ORIGIN_HOST]:
        return 403, "origin not pinned"
    canonical = f"{method} {path} {framing[0]}:{framing[1]} host:{ORIGIN_HOST}"
    tag = hmac.new(_SIGN_KEY, canonical.encode(), hashlib.sha256).hexdigest()
    headers["X-Frame-Integrity"] = [tag]           # 覆盖式写入，客户端同名头被丢弃
    key = cache_key(method, path, headers, framing)
    return 200, f"cache={key[:16]} origin={ORIGIN_HOST} framing={framing[0]}"

if __name__ == "__main__":
    evil = {"Content-Length": ["6"], "Transfer-Encoding": ["chunked"], "Host": [ORIGIN_HOST]}
    print(forward("POST", "/pay", evil, b"0\r\n\r\n"))   # CL+TE 走私尝试 -> 400
    good = {"Content-Length": ["6"], "Host": [ORIGIN_HOST]}
    print(forward("POST", "/pay", good, b"hello!"))      # 正常请求 -> 200
