import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.HexFormat;
import java.util.Map;

public class EdgeCacheForwarder {
    private static final String ORIGIN_HOST = "10.20.0.15"; private static final int ORIGIN_PORT = 8080; // 私有源站硬编码锁定
    static final Map<String, String> CACHE = new HashMap<>();
    public static String forward(InputStream in) throws Exception {
        Map<String, String> h = new HashMap<>();
        BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.ISO_8859_1));
        for (String line; (line = br.readLine()) != null && !line.isEmpty(); ) {
            int c = line.indexOf(':'); if (c > 0) h.put(line.substring(0, c).trim().toLowerCase(), line.substring(c + 1).trim()); // 头名统一小写
        }
        String cl = h.get("content-length"), te = h.get("transfer-encoding");
        if (cl != null && te != null) return respond(400); // 防线1: CL 与 TE 并存直接 400, 显式固定解析顺序
        if (te != null && !te.trim().equalsIgnoreCase("chunked")) return respond(400); // TE 仅接受标准 chunked
        String body = te != null ? readChunked(br) : readN(br, cl == null ? 0 : Integer.parseInt(cl.trim()));
        String key = sha256("GET /api/v1/data|" + cl + "|" + te + "|" + sha256(body)); // 防线2: 缓存键覆盖全部影响头与正文摘要
        String hit = CACHE.get(key); if (hit != null) return hit;
        Socket s = new Socket(ORIGIN_HOST, ORIGIN_PORT); // 防线3: 私有源锁定, 上游不来自请求头
        OutputStream os = s.getOutputStream();
        os.write(("GET /api/v1/data HTTP/1.1\r\nHost: " + ORIGIN_HOST + "\r\nContent-Length: " + body.length() + "\r\nConnection: close\r\n\r\n" + body).getBytes(StandardCharsets.ISO_8859_1)); // 重定框: 以自算 CL 转发
        String resp = new String(s.getInputStream().readAllBytes(), StandardCharsets.ISO_8859_1); s.close();
        String[] p = resp.split("\r\n\r\n", 2);
        if (!p[0].toLowerCase().contains("x-body-digest: " + sha256(p.length > 1 ? p[1] : ""))) return respond(502); // 哈希校验不符即拒
        CACHE.put(key, resp);
        return resp;
    }

    private static String readChunked(BufferedReader br) throws IOException {
        StringBuilder sb = new StringBuilder();
        for (String t; (t = br.readLine()) != null && !t.startsWith("0"); ) {
            char[] b = new char[Integer.parseInt(t.split(";")[0].trim(), 16)]; br.read(b); sb.append(b); br.readLine(); // 剥离分块扩展
        }
        br.readLine(); // 消费终止块后的空行
        return sb.toString();
    }
    private static String readN(BufferedReader br, int n) throws IOException { char[] b = new char[n]; int r = br.read(b); return new String(b, 0, Math.max(r, 0)); }
    private static String respond(int code) { return "HTTP/1.1 " + code + " \r\nContent-Length: 0\r\n\r\n"; }
    private static String sha256(String v) throws Exception { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8))); }
}
