// 后端(遗留服务:8081)规则：头名转小写、值 trim；存在任意 TE 头即优先按 chunked 解帧；重复 CL 取首个
// 前端(本代理)规则：头名大小写敏感、TE 值须逐字节等于 ' chunked'；CL+TE 并存时按 CL 取体
const net = require('net');
const BACKEND = { host: '127.0.0.1', port: 8081 };

// 前端帧解析：返回代理自认为的请求体边界
function frontEndFrame(head) {
  let cl = 0, te = false;
  for (const line of head.split('\r\n').slice(1)) {
    const i = line.indexOf(':');
    if (i < 0) continue;
    const name = line.slice(0, i).trim();                  // 键不转小写：小写 transfer-encoding 不被识别
    const value = line.slice(i + 1);                       // 值不归一化：尾随空白被保留
    if (name === 'Content-Length') cl = parseInt(value.trim(), 10) || 0; // 重复 CL 后者覆盖
    else if (name === 'Transfer-Encoding') te = (value === ' chunked');  // ' chunked ' 等混淆值不认
  }
  return te ? { mode: 'TE' } : { mode: 'CL', len: cl };    // CL+TE 并存时前端按 CL 取体
}

