      return;
    }
    const frame = frontEndFrame(head);                     // 用与后端分歧的规则定界
    const bodyStart = buf.slice(sep + 4);
    const believed = frame.mode === 'CL' ? bodyStart.slice(0, frame.len) : bodyStart;
    if (believed.includes('/admin')) {                     // 防线2：只扫描自认边界内的体
      socket.end('HTTP/1.1 403 Forbidden\r\n\r\n');
