import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
// 后端业务节点：与前置反向代理对 CL/TE 的解析优先级不一致（CWE-444 请求走私）
// 前置代理约定：CL+TE 并存时按 Transfer-Encoding:chunked 定界、头名不区分大小写、重复头取首个；
// 本后端相反：Content-Length 优先、头名精确匹配、重复头末者覆盖，形成走私窗口。
public class BackendHttpWorker {
    // 入口：keep-alive 连接上的原始请求字节流，内容完全由外部可控
    public void serve(InputStream in) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        for (int b; (b = in.read()) != -1; ) buf.write(b);
        String req = new String(buf.toByteArray(), StandardCharsets.ISO_8859_1);
        int offset = 0;
        while (offset < req.length()) {                        // 循环解析：CL 截断后的残余被当作下一请求
            int headEnd = req.indexOf("\r\n\r\n", offset);
            if (headEnd < 0) break;
            Map<String, String> hdr = parseHeaders(req.substring(offset, headEnd));
            int bodyStart = headEnd + 4;
            int bodyLen = hdr.containsKey("Content-Length")    // 缺陷1：CL 优先于 TE，与代理的 TE 优先相反
                    ? Integer.parseInt(hdr.get("Content-Length"))
                    : hdr.containsKey("Transfer-Encoding") ? req.length() - bodyStart : 0;
            route(hdr.get("Request-Line"), req.substring(bodyStart, Math.min(bodyStart + bodyLen, req.length()))); // sink
            offset = bodyStart + bodyLen;                      // 走私的第二个请求留在流水线等待解析
        }
    }
    // 缺陷2：键名未 trim 未小写归一，"transfer-encoding:"/"Content-Length :" 变体被当普通头忽略；
    // 缺陷3：同名重复头后者覆盖前者（HashMap.put），与代理取首策略分歧，可构造双 CL 走私
    private Map<String, String> parseHeaders(String block) {
        Map<String, String> m = new HashMap<>();
        String[] lines = block.split("\r\n");
        m.put("Request-Line", lines[0].trim());
        for (int k = 1; k < lines.length; k++) {
            int i = lines[k].indexOf(':');
            if (i > 0) m.put(lines[k].substring(0, i), lines[k].substring(i + 1).trim());
        }
        return m;
    }
    // 内部路由：默认前置代理已完成 ACL（如拦截 /admin），此处直接执行不再鉴权
    private void route(String requestLine, String body) {
        if (requestLine.startsWith("POST /admin")) System.out.println("admin action: " + body);
        else System.out.println("dispatch: " + requestLine);
    }
}
