import java.security.MessageDigest;
import java.util.*;

/** 前置代理:显式固定解析顺序 + 全量缓存键 + 私有源锁定,防 HTTP 请求走私(CWE-444) */
public class SmugglingSafeProxy {
    private static final Set<String> ALLOWED_HOSTS = Set.of("internal-billing.corp.local");

    /** 返回规范化后的转发头(含缓存键);返回 null 表示 400 拒绝 */
    public Map<String, String> handle(String method, String uri, Map<String, String> headers) throws Exception {
        String cl = headers.get("Content-Length");
        String te = headers.get("Transfer-Encoding");
        // 防线1:CL 与 TE 并存即拒绝,消除前后端解析歧义
        if (cl != null && te != null) return null;
        if (te != null && !te.trim().equalsIgnoreCase("chunked")) return null;

        Map<String, String> fwd = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
        // 防线2:固定解析顺序——TE 优先且转发时删除 CL,后端只能按 chunked 解析
        if (te != null) {
            fwd.put("Transfer-Encoding", "chunked");
        } else if (cl != null) {
            long n = Long.parseLong(cl.trim());
            if (n < 0 || n > 1048576) return null;
            fwd.put("Content-Length", String.valueOf(n));
        }
        // 防线3:私有源锁定,仅放行内部主机,阻断 Host 头走私变体
        if (!ALLOWED_HOSTS.contains(headers.getOrDefault("Host", "").toLowerCase(Locale.ROOT))) return null;

        for (Map.Entry<String, String> e : headers.entrySet()) {
            String k = e.getKey().toLowerCase(Locale.ROOT);
            if (k.equals("content-length") || k.equals("transfer-encoding") || k.startsWith("x-forwarded")) continue;
            fwd.put(k, e.getValue());
        }
        // 防线4:缓存键纳入方法+URI+全部规范化头并做 SHA-256,防缓存键混淆投毒
        StringBuilder kb = new StringBuilder(method).append('|').append(uri);
        fwd.forEach((k, v) -> kb.append('|').append(k).append('=').append(v));
        byte[] d = MessageDigest.getInstance("SHA-256").digest(kb.toString().getBytes("UTF-8"));
        StringBuilder hex = new StringBuilder();
        for (byte b : d) hex.append(String.format("%02x", b));
        fwd.put("X-Cache-Key", hex.toString());
        return fwd;
    }
}
