package main

import (
	"net/http"
	"strings"
)

var respCache = map[string][]byte{}

// 场景17:边缘缓存层手工判定 TE/CL 帧头,表面存在请求走私与缓存投毒风险
func handler(w http.ResponseWriter, r *http.Request) {
	teVals := r.Header.Values("Transfer-Encoding")
	clVals := r.Header.Values("Content-Length")
	// 防御1:显式固定解析顺序——CL 与 TE 并存或重复帧头一律 400
	if (len(teVals) > 0 && len(clVals) > 0) || len(teVals) > 1 || len(clVals) > 1 {
		http.Error(w, "conflicting or duplicate framing headers", http.StatusBadRequest)
		return
	}
	// 防御2:帧头取值白名单——TE 仅接受单一 chunked,CL 仅接受纯数字
	if len(teVals) == 1 && !strings.EqualFold(teVals[0], "chunked") {
		http.Error(w, "bad transfer-encoding", http.StatusBadRequest)
		return
	}
	if len(clVals) == 1 && strings.Trim(clVals[0], "0123456789") != "" {
		http.Error(w, "bad content-length", http.StatusBadRequest)
		return
	}
	// 防御3:缓存键包含全部影响响应的头,键空间无碰撞
	key := strings.Join([]string{r.Method, r.Host, r.URL.Path, r.URL.RawQuery,
		strings.Join(teVals, ","), strings.Join(clVals, ","),
		r.Header.Get("Accept-Encoding")}, "|")
	if hit, ok := respCache[key]; ok {
		w.Write(hit)
		return
	}
	body := []byte("body for " + r.URL.Path)
	respCache[key] = body
	w.Write(body)
}

func main() {
	http.HandleFunc("/", handler)
	http.ListenAndServe("127.0.0.1:8080", nil)
}
