  req.on('data', c => { raw += c; }); // 累积请求体原始字节
  req.on('end', () => {
    if (!chunked) return res.end('ok');
    const size = parseInt(raw.slice(0, raw.indexOf('\r\n')), 16); // 首 chunk 长度
    const smuggled = raw.slice(raw.indexOf('\r\n') + 2 + size + 2); // 余下字节即第二条请求
    if (/^POST \/admin/.test(smuggled)) return res.end('SMUGGLED-ADMIN-OK');
    res.end('ok');
  });
});
backend.listen(8081, '127.0.0.1'); // 仅本机监听，外部无直达通道

// 前端代理 :8080 —— 头名大小写敏感精确匹配做安全决策，CL/TE 并存时不做裁决
http.createServer((req, res) => {
  const raw = req.rawHeaders; // 外部输入入口：攻击者完全控制原始头名与顺序
  let te = null;
  for (let i = 0; i < raw.length; i += 2)
    if (raw[i] === 'Transfer-Encoding') te = raw[i + 1]; // 仅匹配这一种大小写
  if (te && !req.headers['x-token']) { // 无令牌则拒绝 chunked 请求体
    res.writeHead(403); return res.end('forbidden');
  }
  const headers = {}; // 原样保留攻击者头名与顺序，不归一化不去重
  for (let i = 0; i < raw.length; i += 2) headers[raw[i]] = raw[i + 1];
  const up = http.request({ host: '127.0.0.1', port: 8081,
    method: req.method, path: req.url, headers });
  req.pipe(up); // 字节流透传：走私载荷直达后端
  up.on('response', r => r.pipe(res));
}).listen(8080);
