package main
import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

// 前端代理：仅识别规范大小写的头键；CL+TE 并存时 TE 优先，按 chunked 转发全部剩余字节
func frontTE(hdr []string) bool {
	for _, l := range hdr {
		if i := strings.Index(l, ":"); i > 0 && l[:i] == "Transfer-Encoding" { return true }
	}
	return false
}
// 后端：头键统一转小写、重复头取末次；只要存在 CL（即使与 TE 并存）即按 CL 截体
func backCL(hdr []string) int {
	cl := -1
	for _, l := range hdr {
		if i := strings.Index(l, ":"); i > 0 && strings.ToLower(l[:i]) == "content-length" { fmt.Sscanf(strings.TrimSpace(l[i+1:]), "%d", &cl) }
	}
	return cl
}
func reqPath(line string) string {
	f := strings.Fields(line)
	if len(f) > 1 { return f[1] }
	return ""
}
// 入口：攻击者完全可控的原始 HTTP 报文自 stdin 读入
func main() {
	raw, _ := bufio.NewReader(os.Stdin).ReadString(0)
	parts := strings.SplitN(raw+"\r\n\r\n", "\r\n\r\n", 2)
	hl := strings.Split(parts[0], "\r\n")
	if strings.HasPrefix(reqPath(hl[0]), "/admin") { // 前端唯一防线：仅校验首请求行路径
		fmt.Println("FRONTEND BLOCKED"); return
	}
	if !frontTE(hl) { return } // 前端 TE 优先：整个剩余字节按 chunked 实体原样透传（CL 头一并透传）
	body := parts[1]
	n := backCL(hl) // 后端按自身 CL 优先截取请求1实体
	if n < 0 || n > len(body) { n = len(body) }
	h2 := strings.SplitN(body[n:], "\r\n", 2)[0] // CL 之外的字节被后端重新解析为第二个请求
	if strings.HasPrefix(reqPath(h2), "/admin") { // 前端 ACL 管不到后端二次解析
		fmt.Println("BACKEND EXEC ADMIN:", reqPath(h2)) // sink：走私请求直达管理操作
	}
}
