package main

import (
	"crypto/sha256"
	"encoding/hex"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"
)

// 私有源锁定：后端硬编码为内网固定源，客户端请求头无法改写转发目标
var originURL, _ = url.Parse("http://10.10.0.9:8080")

func main() {
	proxy := httputil.NewSingleHostReverseProxy(originURL)
	origDirector := proxy.Director
	proxy.Director = func(req *http.Request) {
		origDirector(req)
		req.Header.Del("Transfer-Encoding")
		req.Header.Del("Content-Length")
		req.Host = originURL.Host
	}
	http.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		cl := r.Header.Get("Content-Length")
		te := r.Header.Get("Transfer-Encoding")
		if cl != "" && te != "" {
			http.Error(w, "ambiguous framing rejected", http.StatusBadRequest)
			return
		}
		if te != "" && !strings.EqualFold(strings.TrimSpace(te), "chunked") {
			http.Error(w, "unsupported framing", http.StatusBadRequest)
			return
		}
		key := sha256.Sum256([]byte(strings.Join([]string{
			r.Method, r.Host, r.URL.RequestURI(),
			r.Header.Get("Accept-Encoding"), r.Header.Get("Authorization"),
			cl, te,
		}, "\x00")))
		w.Header().Set("X-Cache-Key", hex.EncodeToString(key[:]))
		proxy.ServeHTTP(w, r)
	})
	http.ListenAndServe("127.0.0.1:8081", nil)
}
