import hashlib, ipaddress, socket
from http.server import BaseHTTPRequestHandler, HTTPServer

CACHE, RESPONSE_FIELDS = {}, ("Accept", "Accept-Encoding", "Authorization", "Cookie", "X-Role")
PINNED_ORIGIN = "10.0.0.8:8081"  # 私有源锁定
PINNED_ORIGIN_FPR = hashlib.sha256(b"origin-v1|" + PINNED_ORIGIN.encode()).hexdigest()

def parse_body_framing(headers, rfile):
    # 防御1：显式固定解析顺序——TE 优先，CL 仅在无 TE 时生效，双头并存无二义
    te = (headers.get("Transfer-Encoding") or "").strip().lower()
    if "chunked" in te:
        body = b""
        while True:
            size = int(rfile.readline().split(b";")[0].strip() or b"0", 16)
            if size == 0:
                rfile.readline(); break
            body += rfile.read(size); rfile.readline()
        return body
    return rfile.read(int(headers.get("Content-Length", "0")))

def cache_key(method, path, headers):
    # 防御2：缓存键纳入全部影响响应的头，走私前缀无法命中他人缓存槽
    basis = method + " " + path + "|" + "|".join(f"{f}={headers.get(f, '')}" for f in RESPONSE_FIELDS)
    return hashlib.sha256(basis.encode()).hexdigest()

def forward(path, headers, body):
    # 防御3：私有源锁定+绑定哈希校验；转发前剥离原 TE/CL，以单一 Content-Length 重定界
    host, port = PINNED_ORIGIN.rsplit(":", 1)
    if not ipaddress.ip_address(host).is_private or hashlib.sha256(b"origin-v1|" + PINNED_ORIGIN.encode()).hexdigest() != PINNED_ORIGIN_FPR:
        raise RuntimeError("origin bind check failed")
    fwd = "".join(f"{k}: {v}\r\n" for k, v in headers.items()
                  if k.lower() not in ("transfer-encoding", "content-length", "connection"))
    raw = (f"POST {path} HTTP/1.1\r\n{fwd}Content-Length: {len(body)}\r\n\r\n").encode() + body
    with socket.create_connection((host, int(port)), timeout=3) as s:
        s.sendall(raw); return s.recv(65536)

class FrontProxyHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def do_POST(self):
        body = parse_body_framing(self.headers, self.rfile)
        key = cache_key("POST", self.path, self.headers)
        if key not in CACHE:
            CACHE[key] = forward(self.path, self.headers, body)
        self.wfile.write(CACHE[key])
