import java.io.*;
import java.net.*;
import java.util.*;
// 后端业务服务：自研 HTTP 解析器；前置代理按 RFC 大小写不敏感且 TE 优先定界，本端裁决规则与之不一致
public class BackendRequestHandler {
    private final Map<String, String> headers = new HashMap<>();
    // 入口：外部请求经前置代理转发后由本方法从 socket 持续读取（keep-alive 循环）
    public void handle(Socket socket) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        String reqLine;
        while ((reqLine = reader.readLine()) != null && !reqLine.isEmpty()) {
            headers.clear();
            String line;
            while ((line = reader.readLine()) != null && !line.isEmpty()) {
                int idx = line.indexOf(':');
                if (idx <= 0) continue;
                // 缺陷1：同名头直接覆盖，重复 Content-Length 时后端取最后一个值，前置代理取第一个
                headers.put(line.substring(0, idx).trim().toLowerCase(), line.substring(idx + 1).trim());
            }
            dispatch(reqLine, readBody(reader)); // 数据流：socket 字节流 -> headers -> readBody -> dispatch
        }
    }
    private String readBody(BufferedReader reader) throws IOException {
        String te = headers.get("transfer-encoding");
        String cl = headers.get("content-length");
        // 缺陷2：TE 值大小写敏感比较，前置代理按 RFC 大小写不敏感识别 'Chunked' 为分块并放行，本端却回退用 CL 定界
        if ("chunked".equals(te)) {
            StringBuilder sb = new StringBuilder();
            for (int size = Integer.parseInt(reader.readLine(), 16); size > 0; size = Integer.parseInt(reader.readLine(), 16)) {
                char[] c = new char[size];
                reader.read(c);
                sb.append(c);
                reader.readLine();
            }
            return sb.toString();
        }
        char[] buf = new char[cl == null ? 0 : Integer.parseInt(cl)];
        reader.read(buf);
        return new String(buf); // 只消费 CL 字节，剩余分块体被当作下一个请求解析
    }
    // sink：走私的第二请求行直达仅靠前置代理 ACL 保护的内部管理接口
    private void dispatch(String reqLine, String body) {
        System.out.println("route " + reqLine + " body=" + body);
    }
}
