package main

import (
	"bufio"
	"io"
	"net"
	"strconv"
	"strings"
)

// denyPrefix 为前端 ACL：/admin 仅限内网访问，外部请求应在此被拦截
const denyPrefix = "/admin"

// handleClient 对每个外部 TCP 连接调用；后端为遗留服务，按 TE.CL 语义解析
func handleClient(client net.Conn, backendAddr string) {
	defer client.Close()
	br := bufio.NewReader(client)
	head := "" // 原始头块：ACL 判定与原样转发共用同一份字节
	for l, err := br.ReadString('\n'); ; l, err = br.ReadString('\n') {
		head += l
		if err != nil || l == "\r\n" {
			break
		}
	}
	parts := strings.Fields(strings.SplitN(head, "\r\n", 2)[0]) // 入口：外部请求行
	if len(parts) > 1 && strings.HasPrefix(parts[1], denyPrefix) { // 唯一防线：仅查本次请求行
		client.Write([]byte("HTTP/1.1 403 Forbidden\r\n\r\n"))
		return
	}
	// 分歧点：仅认 content-length（大小写不敏感、取第一处），Transfer-Encoding 被完全忽略
	n := 0
	for _, h := range strings.Split(head, "\r\n")[1:] {
		if strings.HasPrefix(strings.ToLower(h), "content-length:") {
			n, _ = strconv.Atoi(strings.TrimSpace(h[15:]))
			break
		}
	}
	be, err := net.Dial("tcp", backendAddr) // 汇：走私请求由此直达按 TE.CL 解析的后端
	if err != nil {
		return
	}
	be.Write([]byte(head))     // 原样转发：TE 头未剥离、重复 CL 未合并
	io.CopyN(be, br, int64(n)) // 仅按 CL 转发 n 字节，多余字节滞留连接流
	io.Copy(be, br)            // 残留透传：第二请求绕过上方 ACL 直达后端
}
