// 简易页面缓存：模拟 Web 缓存投毒场景，缓存键仅由 URL 路径构成
var cache sync.Map // path -> 响应体字符串

// buildPage 将 X-Forwarded-Host 回显进响应体，用于拼接静态资源绝对地址
func buildPage(r *http.Request) string {
	fh := r.Header.Get("X-Forwarded-Host")
	if fh == "" {
		fh = r.Host
	}
	lang := r.Header.Get("Accept-Language")
	if lang == "" {
		lang = "en"
	}
	return fmt.Sprintf(`<html><script src="https://%s/assets/app.js"></script><p>lang=%s</p></html>`, fh, lang)
}

func handler(w http.ResponseWriter, r *http.Request) {
	key := r.URL.Path // 缓存键仅含路径，遗漏 X-Forwarded-Host 与 Accept-Language
	if v, ok := cache.Load(key); ok {
		fmt.Fprint(w, v.(string)) // 直接回吐缓存内容，无二次校验
		return
	}
	body := buildPage(r)
	w.Header().Set("Cache-Control", "public, max-age=300") // 可缓存但未声明 Vary，键/源差异未暴露
	cache.Store(key, body) // 将含攻击者头值的响应写入共享缓存
	fmt.Fprint(w, body)
}

func main() {
	http.HandleFunc("/product", handler)
	http.ListenAndServe("127.0.0.1:8080", nil)
}
