import java.util.HexFormat;
import java.util.LinkedHashMap;
import java.util.Map;

/** 静态资源缓存键与回源地址派生：Web 缓存投毒防护示例 */
public class AssetCacheKeyService {

    // 私有源锁定表：仅精确命中的内部源允许进入缓存内容与缓存键
    private static final Map<String, String> TRUSTED_ORIGIN = new LinkedHashMap<>();
    static {
        TRUSTED_ORIGIN.put("assets.corp.internal", "https://assets.corp.internal");
        TRUSTED_ORIGIN.put("assets-dr.corp.internal", "https://assets-dr.corp.internal");
    }
    // 影响响应的全部头：必须逐一纳入缓存键，杜绝未键控头投毒
    private static final String[] KEYED_HEADERS = {"X-Forwarded-Host", "X-Forwarded-Proto", "Accept-Encoding"};

    public String buildCacheKey(String path, Map<String, String> headers) throws Exception {
        StringBuilder seed = new StringBuilder(path);
        for (String name : KEYED_HEADERS) {
            seed.append('|').append(name).append('=').append(canonicalize(name, headers.get(name)));
        }
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        return HexFormat.of().formatHex(md.digest(seed.toString().getBytes(StandardCharsets.UTF_8)));
    }

    public String buildResourceUrl(String path, Map<String, String> headers) {
        String safePath = path.startsWith("/") ? path : "/" + path;
        String host = canonicalize("X-Forwarded-Host", headers.get("X-Forwarded-Host"));
        return TRUSTED_ORIGIN.get(host) + safePath;
    }

    // 显式固定解析顺序：首个逗号分段 -> 小写 -> 锁定表精确匹配，未命中回退默认源
    static String canonicalize(String header, String raw) {
        String v = raw == null ? "" : raw.split(",")[0].trim().toLowerCase(java.util.Locale.ROOT);
        if ("X-Forwarded-Host".equals(header)) {
            return TRUSTED_ORIGIN.containsKey(v) ? v : "assets.corp.internal";
        }
        if ("X-Forwarded-Proto".equals(header)) {
            return "https"; // 协议钉死，忽略外部可控取值
        }
        return v.isEmpty() ? "none" : v;
    }
}
