import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// 页面渲染服务：按路径缓存首页 HTML，页面内静态资源地址取自代理头
public class PageServlet extends HttpServlet {
    private static final Map<String, String> CACHE = new ConcurrentHashMap<>();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String path = req.getRequestURI();               // 缓存键：仅含路径
        String host = req.getHeader("X-Forwarded-Host"); // 外部输入：代理重写的主机头
        if (host == null || host.isEmpty()) {
            host = req.getServerName();
        }
        // 直接拼接进响应体，未做域名白名单或字符校验
        String body = "<html><script src=\"http://" + host + "/static/app.js\"></script></html>";

        String cached = CACHE.get(path);
        if (cached == null) {
            CACHE.put(path, body); // 键仅含 path，host 未参与键计算：投毒落点
            cached = body;
        }
        resp.setContentType("text/html; charset=UTF-8");
        resp.getWriter().write(cached);
    }
}
