import hashlib
import hmac

# Web缓存投毒场景-5：完整性密钥由部署环境注入后派生（占位输入，非真实凭据）；锁定私有源名单
INTEGRITY_KEY = hmac.digest(b"deploy-injected-secret", b"cache-integrity-v1", hashlib.sha256)
PINNED_ORIGINS = frozenset({"assets.corp.internal:443", "assets-eu.corp.internal:443"})
DEFAULT_ORIGIN = "assets.corp.internal:443"
_cache = {}

def canonical_key(method, path, influencing):
    # 防御A：显式固定解析顺序——影响头按名称排序规范化后并入缓存键
    parts = [method.upper(), path]
    for name in sorted(influencing):
        parts.append(name.lower() + "=" + influencing[name].strip().lower())
    return hashlib.sha256("\n".join(parts).encode()).hexdigest()

def resolve_origin(x_forwarded_host):
    # 防御B：解析结果必须命中锁定私有源名单，否则一律回退默认可信源
    first = x_forwarded_host.split(",")[0].strip().lower()
    return first if first in PINNED_ORIGINS else DEFAULT_ORIGIN

def origin_fetch(origin):
    # 私有源锁定：仅锁定源站对内容做 HMAC 签名后返回
    body = ("served-by=" + origin).encode()
    return body, hmac.new(INTEGRITY_KEY, body, hashlib.sha256).digest()

def verify(body, mac):
    return hmac.compare_digest(mac, hmac.new(INTEGRITY_KEY, body, hashlib.sha256).digest())

def handle(method, path, headers):
    origin = resolve_origin(headers.get("X-Forwarded-Host", ""))
    # 防御C：缓存键包含全部影响响应的头（解析后的 origin），变体无法共享键
    key = canonical_key(method, path, {"x-forwarded-host": origin})
    if key in _cache:
        body, mac = _cache[key]
        if verify(body, mac):  # 防御D：命中时哈希校验，被篡改条目即失效
            return body
        _cache.pop(key, None)
    body, mac = origin_fetch(origin)
    if not verify(body, mac):
        raise ValueError("origin signature mismatch")
    _cache[key] = (body, mac)
    return body
