const crypto = require('crypto');
const cache = new Map(); // key -> { body, mac }

// 防护一：影响响应的全部头按固定顺序纳入缓存键，消除未键化头
const INFLUENCING = ['x-forwarded-host', 'x-forwarded-proto', 'x-original-url', 'accept-language'];
const PRIVATE_ORIGIN = 'assets.internal.corp'; // 私有源锁定目标
const MAC_KEY = Buffer.from(process.env.CACHE_MAC_KEY || '', 'utf8'); // 密钥仅取自环境变量
if (!MAC_KEY.length) throw new Error('CACHE_MAC_KEY env required');

function canonicalKey(req) {
  const parts = ['GET', req.url];
  for (const h of INFLUENCING) { // 显式固定解析顺序：遍历白名单数组而非 Object.keys(req.headers)
    const v = req.headers[h];
    parts.push(h + '=' + (typeof v === 'string' ? v.trim().toLowerCase() : ''));
  }
  return crypto.createHash('sha256').update(parts.join('\n')).digest('hex');
}

function macOf(key, body) {
  return crypto.createHmac('sha256', MAC_KEY).update(key + '\n' + body).digest('hex');
}

function resolveHost(req) {
  const fwd = req.headers['x-forwarded-host'];
  // 私有源锁定：头缺失或严格等于私有源才放行，其余取值一律拒绝（非黑名单、非正则）
  if (fwd === undefined) return PRIVATE_ORIGIN;
  return fwd.trim().toLowerCase() === PRIVATE_ORIGIN ? PRIVATE_ORIGIN : null;
}

function serve(req, res) {
  const host = resolveHost(req);
  if (host === null) { res.writeHead(400); return res.end('untrusted forwarding header'); }
  const key = canonicalKey(req);
  const entry = cache.get(key);
  // 哈希校验：命中后重算 HMAC，键碰撞或缓存体被篡改都会失配并回源重建
  if (entry && macOf(key, entry.body) === entry.mac) {
    res.writeHead(200, { 'content-type': 'text/html', 'cache-control': 'private, max-age=60' });
    return res.end(entry.body);
  }
  const body = '<html>hello from ' + host + req.url + '</html>';
  cache.set(key, { body, mac: macOf(key, body) });
  res.writeHead(200, { 'content-type': 'text/html', 'cache-control': 'private, max-age=60' });
  res.end(body);
}
module.exports = { serve, canonicalKey, resolveHost };
