import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/** Web 缓存投毒场景-11：影响头感知的响应缓存，表面含投毒风险，实际三重防护。 */
public class WebCachePoisonSafe {

    // 防御1：显式固定解析顺序——仅这三个头影响响应，顺序在此锁定，其余头一律忽略
    private static final List<String> INFLUENCERS = Collections.unmodifiableList(
            Arrays.asList("x-forwarded-host", "x-forwarded-proto", "accept-language"));
    // 防御3a：私有源锁定——仅锁定内网源的内容允许进入缓存
    private static final Set<String> LOCKED_ORIGINS = Collections.unmodifiableSet(
            new HashSet<>(Arrays.asList("10.0.0.10", "10.0.0.11")));

    private final Map<String, byte[]> cache = new ConcurrentHashMap<>();

    public byte[] serve(String path, String originAddr, Map<String, List<String>> reqHeaders,
                        byte[] originBody, byte[] originHash) throws Exception {
        if (!LOCKED_ORIGINS.contains(originAddr)) {
            return originBody; // 非锁定源：不读缓存也不写缓存，直接透传
        }
        StringBuilder keyMat = new StringBuilder(path);
        for (String h : INFLUENCERS) { // 固定顺序遍历，解析次序不可被请求方重排
            List<String> v = reqHeaders.get(h);
            keyMat.append('|').append(v == null ? "-" : String.join(",", v));
        }
        // 防御2：缓存键覆盖全部影响头并做哈希，注入白名单外的头不会命中同一键
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        String key = Base64.getEncoder().encodeToString(
                md.digest(keyMat.toString().getBytes(StandardCharsets.UTF_8)));
        byte[] cached = cache.get(key);
        if (cached != null && MessageDigest.isEqual(md.digest(cached), originHash)) {
            return cached; // 防御3b：命中前以锁定源哈希校验，不匹配即失效回源
        }
        cache.put(key, originBody);
        return originBody;
    }
}
