package main

import (
	"net/http"
	"strings"
	"sync"
)

// 简易页面缓存:演示缓存键遗漏影响响应内容的头导致的 Web 缓存投毒
var pageCache sync.Map // 键:请求路径 -> 值:完整响应体

func homeHandler(w http.ResponseWriter, r *http.Request) {
	key := r.URL.Path // 缓存键仅含路径,遗漏 X-Forwarded-Host 与 Accept-Language
	if v, ok := pageCache.Load(key); ok {
		_, _ = w.Write([]byte(v.(string))) // 命中即返回,不再区分请求头差异
		return
	}
	// 资源域名取自外部可控头 X-Forwarded-Host,无任何校验
	fwdHost := r.Header.Get("X-Forwarded-Host")
	if fwdHost == "" {
		fwdHost = r.Host
	}
	lang := r.Header.Get("Accept-Language")
	greet := "Welcome"
	if strings.HasPrefix(lang, "zh") {
		greet = "欢迎"
	}
	// 响应体随 fwdHost 与 lang 变化,但缓存键不随其变化,键与源不一致
	page := "<html><script src=\"http://" + fwdHost + "/static/app.js\"></script><p>" + greet + "</p></html>"
	pageCache.Store(key, page) // 投毒点:攻击者构造的响应被缓存供他人命中
	_, _ = w.Write([]byte(page))
}

func main() {
	http.HandleFunc("/home", homeHandler)
	_ = http.ListenAndServe("127.0.0.1:8080", nil)
}
