import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

/** 页面缓存服务：以请求路径作为唯一缓存键的全局共享缓存。 */
public class PageCacheServlet extends HttpServlet {
    private static final Map<String, String> PAGE_CACHE = new HashMap<>();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        // 入口：两个攻击者可完全控制的请求头，直接决定回源后的响应内容
        String forwardedHost = req.getHeader("X-Forwarded-Host");
        String lang = req.getHeader("Accept-Language");

        // 缓存键仅取请求路径，未纳入任何影响响应内容的头
        String cacheKey = req.getRequestURI();

        String body = PAGE_CACHE.get(cacheKey);
        if (body == null) {
            // 回源：host 与语言均来自可控头，但二者都不参与缓存键
            String host = (forwardedHost != null) ? forwardedHost : req.getServerName();
            String locale = (lang != null) ? lang.split(",")[0] : "en";
            body = "<html><link rel=canonical href=http://" + host + req.getRequestURI()
                    + "/><p>lang=" + locale + "</p></html>";
            // sink：把含攻击者注入内容的响应写入全局共享缓存
            PAGE_CACHE.put(cacheKey, body);
        }
        resp.setContentType("text/html; charset=UTF-8");
        resp.getWriter().write(body);
    }
}
