const crypto = require('crypto');
const http = require('http');

// 私有源锁定：上游源为编译期常量，绝不读取请求头拼接
const UPSTREAM_ORIGIN = 'https://assets.internal.example';
const ORIGIN_PIN = crypto.createHash('sha256').update(UPSTREAM_ORIGIN).digest('hex');

// 显式固定解析顺序：所有影响响应体的头按数组顺序进入缓存键
const INFLUENCING_HEADERS = ['host', 'x-forwarded-host', 'x-forwarded-proto', 'accept'];
const VARY_HEADER = 'Host, X-Forwarded-Host, X-Forwarded-Proto, Accept';

const cacheStore = new Map(); // key -> { body, integrity }

function computeCacheKey(req) {
  const parts = [req.method.toUpperCase(), req.url];
  for (const h of INFLUENCING_HEADERS) {
    parts.push(h + '=' + String(req.headers[h] || '').trim().toLowerCase());
  }
  parts.push('pin=' + ORIGIN_PIN);
  return crypto.createHash('sha256').update(parts.join('\u0001')).digest('hex');
}

function renderPage(fwdHost) {
  // 危险表象：请求方可控头被反射进响应体（若缓存键未覆盖即为投毒点）
  return '<link rel=canonical href="https://' + fwdHost + '/index.html">';
}

http.createServer((req, res) => {
  const key = computeCacheKey(req);
  const hit = cacheStore.get(key);
  if (hit && crypto.createHash('sha256').update(key + hit.body).digest('hex') === hit.integrity) {
    res.writeHead(200, { 'content-type': 'text/html', vary: VARY_HEADER, 'cache-control': 'public, max-age=60' });
    return res.end(hit.body);
  }
  // CWE-525 防护：携带凭据的请求一律不落缓存
  const cacheable = !req.headers['authorization'] && !req.headers['cookie'];
  const headers = { 'content-type': 'text/html', vary: VARY_HEADER, 'cache-control': cacheable ? 'public, max-age=60' : 'no-store' };
  const body = renderPage(String(req.headers['x-forwarded-host'] || new URL(UPSTREAM_ORIGIN).host));
  if (cacheable) {
    cacheStore.set(key, { body, integrity: crypto.createHash('sha256').update(key + body).digest('hex') });
  }
  res.writeHead(200, headers);
  res.end(body);
}).listen(8080);
