import hashlib

# 私有源锁定：缓存与响应只允许绑定到该配置常量源
LOCKED_ORIGIN = "https://assets.internal.example"
# 显式固定解析顺序：仅以下头会影响响应内容，顺序固定，其余头一律不参与键生成
VARY_HEADERS = ("accept-language", "accept-encoding")


def build_cache_key(method, path, headers):
    parts = [method.upper(), path, LOCKED_ORIGIN]
    for name in VARY_HEADERS:
        value = headers.get(name, "-").strip().lower()
        parts.append(name + "=" + value)
    return hashlib.sha256("|".join(parts).encode("utf-8")).hexdigest()


def store_entry(cache, method, path, headers, body):
    key = build_cache_key(method, path, headers)
    cache[key] = {"body": body, "sha256": hashlib.sha256(body).hexdigest(), "origin": LOCKED_ORIGIN}


def serve_cached(cache, method, path, headers):
    key = build_cache_key(method, path, headers)
    entry = cache.get(key)
    if entry is None:
        return None
    if entry.get("origin") != LOCKED_ORIGIN:
        return None
    if hashlib.sha256(entry["body"]).hexdigest() != entry["sha256"]:
        cache.pop(key, None)
        return None
    return entry["body"]


if __name__ == "__main__":
    cache = {}
    req_headers = {"accept-language": "zh-CN", "x-forwarded-host": "attacker.example"}
