                 .append(raw == null ? "-" : raw.split(",")[0].trim());
        }
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(
                System.getenv("CACHE_HMAC_KEY").getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
        return HexFormat.of().formatHex(mac.doFinal(canon.toString().getBytes(StandardCharsets.UTF_8)));
