class PageCache {
    static final ConcurrentHashMap<String, String> STORE = new ConcurrentHashMap<>();
    static String get(String key) { return STORE.get(key); }
    static void put(String key, String val) { STORE.put(key, val); }
}

public class HomeServlet extends HttpServlet {
    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String cacheKey = req.getRequestURI();          // 缓存键：仅取路径，不含任何请求头
        String hit = PageCache.get(cacheKey);
        if (hit != null) { resp.getWriter().write(hit); return; }

        // 客户端可控头：决定页面 canonical 链接与静态资源域名，却不参与缓存键
        String fwdHost = req.getHeader("X-Forwarded-Host");
        String host = (fwdHost == null || fwdHost.isEmpty()) ? req.getServerName() : fwdHost;

        String page = "<html><head><link rel=canonical href=\"https://" + host
                + "/home\"/><script src=\"https://" + host + "/app.js\"></script></head><body>首页</body></html>";
        PageCache.put(cacheKey, page);                  // 未声明 Vary: X-Forwarded-Host 即无条件写入共享缓存
        resp.setContentType("text/html; charset=UTF-8");
        resp.getWriter().write(page);
    }
}
