package main
import (
	"crypto/sha256"
	"io"
	"net/http"
	"strings"
	"sync"
)
// 影响响应内容的全部请求头：缓存键完整覆盖，并按本切片固定顺序解析
var influential = []string{"Accept", "Accept-Language", "X-Forwarded-Host", "X-Forwarded-Proto"}
// 源站锁定为内网私有地址，绝不取自用户可控的 X-Forwarded-Host
const originLocked = "http://10.0.0.2:8080"
type entry struct{ body []byte; sum [32]byte }
var mu sync.RWMutex
var store = map[string]entry{}

func cacheKey(r *http.Request) string {
	parts := []string{r.Method, r.URL.Path, r.URL.RawQuery}
	for _, h := range influential {
		parts = append(parts, strings.ToLower(h)+"="+strings.ToLower(strings.TrimSpace(r.Header.Get(h))))
	}
	return string(sha256.Sum256([]byte(strings.Join(parts, "\x00")))[:])
}

func handler(w http.ResponseWriter, r *http.Request) {
	key := cacheKey(r)
	mu.RLock()
	e, hit := store[key]
	mu.RUnlock()
	if hit && sha256.Sum256(e.body) == e.sum { // 哈希校验通过才回放缓存
		w.Write(e.body)
		return
	}
	resp, err := http.Get(originLocked + r.URL.EscapedPath() + "?" + r.URL.RawQuery)
	if err != nil {
		http.Error(w, "upstream", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	mu.Lock()
	store[key] = entry{body, sha256.Sum256(body)}
	mu.Unlock()
	w.Write(body)
}
