const crypto = require('crypto');

const CACHE = new Map();                       // 场景29: Web缓存投毒检测点
const TTL_MS = 60000;
const ALLOWED_HOSTS = new Set(['shop.internal.example', 'cdn.shop.internal.example']);

function pickHeader(headers, name) {           // 显式固定解析顺序: 只取首个值
  const raw = headers[name];
  const first = Array.isArray(raw) ? raw[0] : String(raw || '');
  return first.split(',')[0].trim().toLowerCase();
}

function buildCacheKey(req) {                  // 缓存键覆盖全部影响响应的头
  const host = pickHeader(req.headers, 'x-forwarded-host') || req.headers.host;
  const proto = pickHeader(req.headers, 'x-forwarded-proto') || 'https';
  const lang = pickHeader(req.headers, 'accept-language') || 'en';
  return proto + '://' + host + req.url + '#lang=' + lang;
}

function tagOf(key, body) {                    // 键体绑定哈希, 供回放校验
  return crypto.createHash('sha256').update(key + '\u0000' + body).digest('hex');
}

function handleRequest(req, res) {
  const host = pickHeader(req.headers, 'x-forwarded-host') || req.headers.host;
  if (!ALLOWED_HOSTS.has(host)) {              // 私有源锁定: 非白名单不缓存不回显
    res.set('Cache-Control', 'no-store');
    return res.status(403).send('forbidden origin');
  }
  const key = buildCacheKey(req);
  const hit = CACHE.get(key);
  if (hit && tagOf(key, hit.body) === hit.tag && Date.now() - hit.t < TTL_MS) {
    res.set('Vary', 'X-Forwarded-Host, X-Forwarded-Proto, Accept-Language');
    return res.send(hit.body);
  }
  const body = '<link rel="canonical" href="https://' + host + '/">';
  CACHE.set(key, { t: Date.now(), tag: tagOf(key, body), body });
  res.set('Vary', 'X-Forwarded-Host, X-Forwarded-Proto, Accept-Language');
  res.set('Cache-Control', 'public, max-age=60');
  res.send(body);
}

module.exports = { handleRequest, buildCacheKey };
