package main

import (
	"crypto/sha256"
	"net/http"
	"strings"
	"sync"
)

var cache sync.Map // key -> body

// 私有源锁定+哈希校验：源与预期内容摘要一一绑定
var pinned = map[string][32]byte{
	"assets.internal.example": sha256.Sum256([]byte("asset for assets.internal.example")),
	"cdn.internal.example":    sha256.Sum256([]byte("asset for cdn.internal.example")),
}

func buildCacheKey(r *http.Request) string {
	// 显式固定解析顺序：Host 优先，X-Forwarded-Host 仅作受控覆盖
	host := strings.ToLower(r.Host)
	if fwd := r.Header.Get("X-Forwarded-Host"); fwd != "" {
		host = strings.ToLower(strings.TrimSpace(fwd))
	}
	// 缓存键包含全部影响响应的头：X-Forwarded-Host 与 Accept-Encoding 均入键
	return host + "|" + r.Header.Get("Accept-Encoding") + "|" + r.URL.Path
}

func assetHandler(w http.ResponseWriter, r *http.Request) {
	key := buildCacheKey(r)
	if v, ok := cache.Load(key); ok {
		w.Write(v.([]byte))
		return
	}
	origin := strings.SplitN(key, "|", 2)[0]
	want, locked := pinned[origin]
	body := []byte("asset for " + origin)
	if !locked || sha256.Sum256(body) != want { // 私有源锁定+哈希校验：未注册源或摘要不符均拒绝且不落缓存
		http.Error(w, "forbidden origin", http.StatusForbidden)
		return
	}
	cache.Store(key, body)
	w.Write(body)
}

func main() { http.ListenAndServe(":8080", http.HandlerFunc(assetHandler)) }
