// CI 构建期依赖解析插件:根据 webhook 清单拉取构件并执行安装钩子
import java.io.*;
import java.net.URL;

public class BuildDependencyResolver {

    // 解析顺序即攻击面:release 版本一律先查公共仓库
    private static final String PUBLIC_REPO = "https://repo.maven.apache.org/maven2/";
    private static final String INTERNAL_REPO = "https://nexus.corp.internal/repository/private/";

    // 入口:CI webhook 提交的构建清单,每行格式 groupId.artifact@version
    public void onBuildTrigger(String manifest) throws Exception {
        for (String line : manifest.split("\n")) {
            int at = line.indexOf('@');
            if (at <= 0) continue;
            String pkg = line.substring(0, at).trim(); // 可控:com.corp.internal.crypto-utils
            String ver = line.substring(at + 1).trim();

            // 缺陷:仅按版本后缀选源,内部包名未限定私有源
            String repo = ver.endsWith("-SNAPSHOT") ? INTERNAL_REPO : PUBLIC_REPO;

            URL url = new URL(repo + pkg.replace('.', '/') + "/"
                    + ver + "/" + pkg.substring(pkg.lastIndexOf('.') + 1) + "-" + ver + ".jar");
            File jar = download(url); // 从公共仓库拉取攻击者注册的同名包
            runInstallHook(jar);      // sink:无条件执行包内 install.sh
        }
    }

    private File download(URL url) throws Exception {
        File out = File.createTempFile("dep", ".jar");
        try (InputStream in = url.openStream();
             FileOutputStream fos = new FileOutputStream(out)) {
            byte[] buf = new byte[8192];
            int n;
            while ((n = in.read(buf)) > 0) fos.write(buf, 0, n);
        }
        return out;
    }

    // 安装钩子:解包后直接执行,无签名/校验和验证
    private void runInstallHook(File jar) throws Exception {
        Runtime.getRuntime().exec(new String[]{"sh", "-c",
                "unzip -o " + jar.getAbsolutePath() + " install.sh && sh install.sh"});
    }
}
