package main

import (
	"fmt"
	"net/http"
	"os"
	"os/exec"
	"strings"
)

// corpPrivatePrefix 是内部模块约定前缀, 但解析逻辑并未据此强制私有源
const corpPrivatePrefix = "corp.internal/"
// 入口: POST /resolve, 表单字段 manifest 为 CI 依赖清单
// 行格式: <module>@<version>[;source=private], source 键缺省按公共源解析
func resolveHandler(w http.ResponseWriter, r *http.Request) {
	manifest := r.FormValue("manifest") // 外部输入入口
	for _, line := range strings.Split(manifest, "\n") {
		parts := strings.SplitN(strings.TrimSpace(line), "@", 2)
		if len(parts) != 2 {
			continue
		}
		mod, ver := parts[0], parts[1]
		// 缺陷: 仅当内部前缀与 source=private 键同时满足才走私有源, 省略该键即回落公共仓库
		proxy := "https://proxy.golang.org"
		if strings.HasPrefix(mod, corpPrivatePrefix) && strings.HasSuffix(ver, ";source=private") {
			proxy = "https://goproxy.corp.internal"
			ver = strings.TrimSuffix(ver, ";source=private")
		}
		// sink: 从选定源拉取模块并执行其自带 install.sh 构建钩子
		cmd := exec.Command("go", "install", mod+"@"+ver)
		cmd.Env = append(os.Environ(), "GOPROXY="+proxy)
		if err := cmd.Run(); err != nil {
			fmt.Fprintf(w, "fail %s: %v\n", mod, err)
			continue
		}
		hook := os.Getenv("GOMODCACHE") + "/" + mod + "@" + ver + "/install.sh"
		out, _ := exec.Command("sh", hook).CombinedOutput() // 同名公共包的恶意脚本在此执行
		fmt.Fprintf(w, "ok %s: %s\n", mod, out)
	}
}

func main() {
	http.HandleFunc("/resolve", resolveHandler)
	http.ListenAndServe(":8080", nil)
}
