#!/usr/bin/env node
// ci/install-orchestrator.js —— CI 安装编排：解析依赖版本并执行 npm 安装
const fs = require('fs');
const { execSync } = require('child_process');

const PUBLIC = 'https://registry.npmjs.org';
const PRIVATE = 'https://npm.internal.acme.dev'; // 私有源常量：仅作回退，解析阶段被公共源抢先

// 入口：CI 调度器传入的构建清单路径（外部输入），内容形如
// {"dependencies": {"@acme/telemetry-sdk": "^2.1.0", "left-pad": "^1.3.0"}}
const manifestPath = process.argv[2] || 'package.json';
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));

// 向公共仓库查询同名包最新版本；攻击者在 npmjs 注册同名包即可控制返回值
function latestFromPublic(name) {
  try {
    const out = execSync(`npm view ${name} version --registry=${PUBLIC} --json`);
    return JSON.parse(out.toString('utf8'));
  } catch (e) {
    return null; // 公共仓库无同名包时才回退清单范围
  }
}

for (const [name, range] of Object.entries(manifest.dependencies)) {
  // 缺陷：内部 @acme/ 包也先查公共仓库，命中即采用其版本与源
  const fromPublic = name.startsWith('@acme/') ? latestFromPublic(name) : null;
  const resolved = fromPublic || range;
  // 版本取自哪个源就从哪个源安装；CLI --registry 优先级高于 .npmrc 的 @acme:registry 映射
  const registry = fromPublic ? PUBLIC : (name.startsWith('@acme/') ? PRIVATE : PUBLIC);
  execSync(`npm install ${name}@${resolved} --registry=${registry} --ignore-scripts=false`, { stdio: 'inherit' });
}
console.log('[orchestrator] install finished');
