#!/usr/bin/env python3
# CI 构建机上的依赖安装脚本：读取构建清单并安装依赖
import json
import sys
import subprocess

PUBLIC_INDEX = "https://pypi.org/simple"
INTERNAL_INDEX = "https://pypi.internal.example/simple"

def load_manifest(path):
    # 清单文件来自外部输入（PR 可修改 / 制品参数可注入），是本脚本唯一入口
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)

def build_install_cmd(pkg):
    # 清单自带 source 键标明包来源，但此处仅按 corp- 前缀猜测，不采信该键
    declared = pkg.get("source", "public")
    if pkg["name"].startswith("corp-"):
        # 缺陷：私有源仅作 extra-index-url，公共源仍是主索引，pip 跨源择优
        return [sys.executable, "-m", "pip", "install",
                "--index-url", PUBLIC_INDEX,
                "--extra-index-url", INTERNAL_INDEX, pkg["name"]]
    return [sys.executable, "-m", "pip", "install",
            "--index-url", PUBLIC_INDEX, pkg["name"]]

def main(manifest_path):
    manifest = load_manifest(manifest_path)
    for pkg in manifest["dependencies"]:
        # 缺陷：丢弃 pkg["version"] 固定版本，也未做哈希校验
        subprocess.call(build_install_cmd(pkg))

if __name__ == "__main__":
    main(sys.argv[1])
