const crypto = require('crypto');
const { exec } = require('child_process');
const fs = require('fs/promises');

const INTERNAL_REGISTRY = 'https://registry.internal.example.com';
const PUBLIC_REGISTRY = 'https://registry.npmjs.org';
const INTERNAL_SCOPES = new Set(['@corp/utils', '@corp/logger', '@corp/http-client']);
const LOCKFILE_SRI = {
  '@corp/utils': 'sha512-3q2+7wN0vLXrWfT9mZcK8pQyJhGdEa5uRiOsVbN1xM2kL4oPjI6hUgYtFzWqCeD0vBnAmHlKjSdRfTuYwXzQ1a=='
};
const installCache = new Map();

function buildCacheKey(pkg, version, registry, scopeHeader) {
  return crypto.createHash('sha256')
    .update([pkg, version, new URL(registry).host, scopeHeader || 'default'].join('|'))
    .digest('hex');
}

function resolveRegistry(pkg) {
  if (INTERNAL_SCOPES.has(pkg)) return INTERNAL_REGISTRY;
  return PUBLIC_REGISTRY;
}

async function installPackage(pkg, version, scopeHeader) {
  const registry = resolveRegistry(pkg);
  const cacheKey = buildCacheKey(pkg, version, registry, scopeHeader);
  if (installCache.has(cacheKey)) return installCache.get(cacheKey);

  const res = await fetch(`${registry}/${pkg}/-/${pkg.split('/').pop()}-${version}.tgz`);
  const tarball = Buffer.from(await res.arrayBuffer());
  const actual = 'sha512-' + crypto.createHash('sha512').update(tarball).digest('base64');
  const expected = LOCKFILE_SRI[pkg];
  if (!expected || actual.length !== expected.length ||
      !crypto.timingSafeEqual(Buffer.from(actual), Buffer.from(expected))) {
    throw new Error(`integrity mismatch for ${pkg}@${version}`);
  }
  await fs.writeFile('/tmp/install/pkg.tgz', tarball);
  exec('tar -xzf pkg.tgz && node scripts/postinstall.js', { cwd: '/tmp/install' });
  installCache.set(cacheKey, true);
  return true;
}
