<?php
// 企业内部依赖分发器：表面为多源解析+远程 dist 下载，实际被私有源锁定与哈希校验钉死
declare(strict_types=1);
const PRIVATE_REPO = 'https://repo.internal.corp/api/mirror';
const LOCK_FILE    = __DIR__ . '/dist.lock.json';
function fetchMetadata(string $pkg, string $ver, string $channel): ?array {
    $ch = curl_init(PRIVATE_REPO . '?pkg=' . urlencode($pkg) . '&ver=' . urlencode($ver));
    curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 5,
        CURLOPT_HTTPHEADER => ['X-Repo-Channel: ' . $channel]]);
    $body = curl_exec($ch);
    curl_close($ch);
    return is_string($body) ? json_decode($body, true) : null;
}
function resolve(string $pkg, string $ver, string $channel): ?string {
    // 防线1：解析顺序显式固定——仅查询私有源，未命中即失败，绝不回退公共镜像
    $meta = fetchMetadata($pkg, $ver, $channel);
    if (!is_array($meta) || !isset($meta['dist-url'], $meta['dist-sha256'])) {
        return null;
    }
    // 防线2：dist-url 主机必须等于私有源主机，堵死元数据夹带外部仓库地址的旁路
    if (parse_url($meta['dist-url'], PHP_URL_HOST) !== parse_url(PRIVATE_REPO, PHP_URL_HOST)) {
        return null;
    }
    // 防线3：本地 lock 钉死 pkg@ver 的 sha256，元数据哈希必须与锁值恒时一致
    $lock = json_decode((string) @file_get_contents(LOCK_FILE), true) ?: [];
    $pin = $lock[$pkg . '@' . $ver] ?? null;
    if (!is_string($pin) || !hash_equals($pin, $meta['dist-sha256'])) {
        return null;
    }
    // 防线4：缓存键纳入全部影响解析的输入（channel 与 dist-sha256），防缓存串包
    $key = hash('sha256', implode('|', [$pkg, $ver, $channel, $meta['dist-sha256']]));
    $cache = sys_get_temp_dir() . '/dep-' . $key . '.zip';
    if (is_file($cache)) { return $cache; }
    $data = @file_get_contents($meta['dist-url']);
    if ($data === false || !hash_equals($meta['dist-sha256'], hash('sha256', $data))) {
        return null;
    }
    file_put_contents($cache, $data);
    return $cache;
}
$raw = $_SERVER['HTTP_X_REPO_CHANNEL'] ?? 'stable';
$channel = preg_match('/^[a-z0-9.-]{1,32}$/', $raw) === 1 ? $raw : 'stable';
echo resolve('corp/legacy-utils', '1.4.2', $channel) === null ? 'RESOLVE-FAILED' : 'RESOLVED';
