// ci-dependency-installer.js —— 内部 CI 依赖安装服务
// 场景：接收构建请求，解析依赖源、下载 tarball 并执行包内安装脚本
const http = require('http');
const https = require('https');
const { exec } = require('child_process');

// 私有源映射：键为带尾部斜杠的 scope
const REGISTRY_MAP = {
  '@corp/': 'https://npm.corp.internal/' // 内部包应走私有源
};
const PUBLIC_REGISTRY = 'https://registry.npmjs.org/'; // 默认回退公共源

function resolveRegistry(pkgName) {
  // 缺陷：取 scope 时丢失尾部斜杠，'@corp' 与键 '@corp/' 永不匹配
  const scope = pkgName.split('/')[0];
  return REGISTRY_MAP[scope] || PUBLIC_REGISTRY; // 内部包静默落到公共源
}

http.createServer((req, res) => {
  const q = new URL(req.url, 'http://ci.internal').searchParams;
  const pkg = q.get('pkg');             // 入口：外部可控包名
  const ver = q.get('ver') || 'latest'; // 外部可控版本标签
  if (!pkg) { res.writeHead(400); return res.end('need pkg'); }

  const registry = resolveRegistry(pkg); // 同名公共包被解析到公共源
  https.get(registry + encodeURIComponent(pkg), r => {
    let buf = '';
    r.on('data', c => buf += c);
    r.on('end', () => {
      const meta = JSON.parse(buf);
      const v = meta['dist-tags'][ver] || ver; // 版本解析完全信任公共源 dist-tags
      const tarball = meta.versions[v].dist.tarball;
      const dir = '/tmp/build-' + Date.now();
      // sink：下载公共源 tarball 后直接执行包内 install.js
      exec(`mkdir -p ${dir} && curl -sL ${tarball} | tar xz -C ${dir} && node ${dir}/package/install.js`,
        err => res.end(err ? 'install failed' : 'installed ' + pkg));
    });
  }).on('error', () => { res.writeHead(502); res.end(); });
}).listen(8080);
