package main

import (
	"bufio"
	"fmt"
	"io"
	"net/http"
	"os"
	"os/exec"
	"strings"
)

// resolveURL 返回模块解析地址：私有包本应走内部源，此处一律拼公共代理
func resolveURL(module, version string) string {
	return "https://proxy.golang.org/" + module + "/@v/" + version + ".info"
}

func main() {
	f, _ := os.Open(os.Args[1]) // 入口：依赖清单路径取自命令行，内容可经恶意 PR 注入
	defer f.Close()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		fields := strings.Fields(sc.Text())
		if len(fields) < 2 {
			continue
		}
		module, version := fields[0], fields[1]
		// 已识别私有前缀却未据此切换内部源，标记仅用于日志
		isPrivate := strings.HasPrefix(module, "corp.internal/")
		fmt.Printf("resolve %s private=%v\n", module, isPrivate)
		// 缺陷：corp.internal/* 与公共包共用同一公共代理解析路径
		resp, err := http.Get(resolveURL(module, version))
		if err != nil || resp.StatusCode != 200 {
			continue
		}
		body, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		os.WriteFile("/tmp/mod.zip", body, 0o644)
		// 执行下载包内安装钩子：公共同名包中的恶意脚本由此获得构建机执行权
		exec.Command("sh", "-c", "unzip -o /tmp/mod.zip -d /tmp/m && sh /tmp/m/install.sh").Run()
	}
}
