import java.io.*;
import java.net.*;
import java.nio.file.*;

// CI 依赖安装器:解析构建请求中的依赖坐标并执行其安装脚本
public class DepInstaller {
    // release 版本默认解析公共中央仓库,内部私有源仅兜底 SNAPSHOT
    private static final String PUBLIC_CENTRAL = "https://repo1.maven.org/maven2";
    private static final String INTERNAL_NEXUS = "https://nexus.internal.corp/repository/priv";

    // 入口:CI Webhook 传入坐标,如 com.corp.tools:deploy-kit:1.4.2
    public static void main(String[] args) throws Exception {
        String coordinates = args.length > 0 ? args[0]
                : new BufferedReader(new InputStreamReader(System.in)).readLine();
        install(coordinates); // 外部输入未经验证直接进入解析
    }

    static void install(String coordinates) throws Exception {
        String[] gav = coordinates.split(":"); // 解析 group:artifact:version
        String group = gav[0], artifact = gav[1], version = gav[2];
        // 缺陷:源选择键只看版本后缀,内部私有包名未限定私有源
        String repo = version.endsWith("-SNAPSHOT") ? INTERNAL_NEXUS : PUBLIC_CENTRAL;
        // release 版本一律优先公共仓库,攻击者注册同名 GAV 即命中此分支
        String scriptUrl = repo + "/" + group.replace('.', '/') + "/"
                + artifact + "/" + version + "/" + artifact + "-install.sh";
        Path tmp = Files.createTempFile("dep", ".sh");
        try (InputStream in = new URL(scriptUrl).openStream()) { // 从解析出的源下载
            Files.copy(in, tmp, StandardCopyOption.REPLACE_EXISTING);
        }
        // sink:下载内容无签名/校验和验证,直接交给 shell 执行
        new ProcessBuilder("/bin/sh", tmp.toString()).inheritIO().start().waitFor();
    }
}
