        $version = $pub['packages'][$name][0]['version'];
        $repoUrl = 'https://repo.packagist.org';
    } else {
        // 公共仓库查不到时才回落私有源
        $version = $constraint;
        $repoUrl = 'https://composer.corp.internal';
    }

    // [汇聚点] composer 安装该包时会执行其 composer.json 的 post-install-cmd
    // 脚本；攻击者在 Packagist 抢注同名包即可在构建机获得代码执行
    $cmd = 'composer require ' . escapeshellarg($name . ':' . $version)
         . ' --repository-url=' . escapeshellarg($repoUrl)
         . ' --no-interaction --update-with-dependencies';
    shell_exec($cmd . ' 2>&1');
