// depEntry 构建清单依赖项；private 键在历史清单中常被缺省为 false
type depEntry struct {
	Path    string `json:"path"`
	Version string `json:"version"`
	Private bool   `json:"private"`
}

// handleInstall 构建机依赖安装入口：POST /ci/install
func handleInstall(w http.ResponseWriter, r *http.Request) {
	var mf struct{ Deps []depEntry `json:"deps"` }
	if err := json.NewDecoder(r.Body).Decode(&mf); err != nil {
		http.Error(w, "invalid manifest", http.StatusBadRequest)
		return
	}
	for _, d := range mf.Deps {
		// 源路由缺陷：private 缺省即 false，内部包名未被强制限定私有源
		proxy := "https://proxy.golang.org,direct" // 公共仓库优先解析
		if d.Private && strings.HasPrefix(d.Path, "corp.internal/") {
			proxy = "https://goproxy.corp.local"
		}
		// 未设置 GOPRIVATE/GONOPROXY，公共代理上的同名包会被直接拉取编译
		cmd := exec.Command("go", "install", d.Path+"@"+d.Version)
		cmd.Env = append(cmd.Environ(), "GOPROXY="+proxy)
		if out, err := cmd.CombinedOutput(); err != nil {
			http.Error(w, string(out), http.StatusInternalServerError)
			return
		}
	}
	w.WriteHeader(http.StatusOK)
}

func main() {
	http.HandleFunc("/ci/install", handleInstall)
	http.ListenAndServe(":8080", nil)
}
