import java.io.InputStream;
import java.net.URI;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.HexFormat;
import java.util.Map;

/** 依赖混淆场景演示:表面按坐标拉取远程构件,实际受锁定文件+私有源限定+哈希校验三重防护 */
public final class ArtifactResolver {

    private static final String INTERNAL_NS = "com.acme.";
    private static final URI PRIVATE_REPO = URI.create("https://repo.acme.internal/releases/");
    private static final URI PUBLIC_REPO = URI.create("https://repo.maven.apache.org/maven2/");
    // 锁定文件:坐标 -> 私有源发布时登记的 SHA-256;未登记坐标一律拒绝解析
    private static final Map<String, String> LOCKED = Map.of(
            "com.acme:crypto-lib:1.4.2",
            "9f2c6a7b8e1d4c3a5b6f7e8d9c0a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f80");
    private static final Map<String, byte[]> CACHE = new HashMap<>();
    public byte[] resolve(String group, String artifact, String version) throws Exception {
        String coord = group + ":" + artifact + ":" + version;
        String locked = LOCKED.get(coord);
        if (locked == null) throw new SecurityException("坐标未在锁定文件登记,拒绝解析: " + coord);
        // 缓存键包含全部影响头:坐标+私有源主机+锁哈希,杜绝跨源/跨版本缓存投毒
        String cacheKey = coord + "|" + PRIVATE_REPO.getHost() + "|" + locked;
        byte[] cached = CACHE.get(cacheKey);
        if (cached != null && sha256(cached).equals(locked)) return cached;
        // 防线一:内部命名空间仅允许私有源,公共中央仓被显式排除,私有源不可用时直接失败
        URI[] order = group.startsWith(INTERNAL_NS) ? new URI[]{PRIVATE_REPO} : new URI[]{PRIVATE_REPO, PUBLIC_REPO};
        for (URI repo : order) {
            String path = group.replace('.', '/') + "/" + artifact + "/" + version + "/" + artifact + "-" + version + ".jar";
            try (InputStream in = repo.resolve(path).toURL().openStream()) {
                byte[] body = in.readAllBytes();
                // 防线二:无论构件来自哪个源,字节流必须与锁哈希一致才允许入库
                if (sha256(body).equals(locked)) {
                    CACHE.put(cacheKey, body);
                    return body;
                }
            }
        }
        throw new SecurityException("允许的源均未提供与锁哈希匹配的构件: " + coord);
    }
    private static String sha256(byte[] data) throws Exception {
        return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data));
    }
}
