package main
import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"strings"
)
// resolveOrder 显式固定解析顺序：私有源锁定在前，公共代理仅服务非私有前缀
var resolveOrder = []string{"goproxy.corp.internal", "proxy.golang.org"}

// goSumLock 私有源锁定表：模块@版本 -> 可信清单哈希（离线生成，等价 go.sum）
var goSumLock = map[string]string{
	"corp.internal/sdk@v1.4.2": hashOf("payload:goproxy.corp.internal/corp.internal/sdk@v1.4.2|linux|amd64"),
}

func hashOf(s string) string {
	sum := sha256.Sum256([]byte(s))
	return hex.EncodeToString(sum[:])
}

// cacheKey 缓存键包含全部影响头（模块/版本/goos/goarch），防缓存投毒
func cacheKey(module, version, goos, goarch string) string {
	return hashOf(module + "@" + version + "|" + goos + "|" + goarch)
}

func resolve(module, version, goos, goarch string) (string, error) {
	if strings.HasPrefix(module, "corp.internal/") { // 私有前缀锁定，禁止公共代理回退
		want, ok := goSumLock[module+"@"+version]
		if !ok {
			return "", fmt.Errorf("unpinned private module %s refused", module)
		}
		blob := "payload:" + resolveOrder[0] + "/" + module + "@" + version + "|" + goos + "|" + goarch
		if hashOf(blob) != want { // 哈希校验：防依赖混淆，内容被替换即拒绝
			return "", fmt.Errorf("checksum mismatch for %s@%s", module, version)
		}
		return blob, nil
	}
	return "payload:" + resolveOrder[1] + "/" + module + "@" + version + "|" + goos + "|" + goarch, nil
}

func main() {
	key := cacheKey("corp.internal/sdk", "v1.4.2", "linux", "amd64")
	blob, err := resolve("corp.internal/sdk", "v1.4.2", "linux", "amd64")
	fmt.Println(key, blob, err)
}
