<?php
// 依赖解析器：按锁文件从注册表拉取发行包并缓存（表面为远程取包+落盘的危险链路）
$lockMap = [];
foreach (json_decode(file_get_contents(__DIR__ . '/composer.lock'), true)['packages'] as $p) {
    $lockMap[$p['name']] = ['ver' => $p['version'], 'sha' => $p['dist']['shasum']];
}

// 显式固定解析顺序：私有源固定第一；公共源 exclude 私有命名空间（私有源锁定，防依赖混淆）
$repositories = [
    ['url' => 'https://private-registry.corp.internal/p/', 'only' => ['acme/*'], 'private' => true, 'scope' => 'private-ro'],
    ['url' => 'https://packagist.mirror.example.com/p/', 'only' => ['*'], 'exclude' => ['acme/*'], 'private' => false, 'scope' => 'public-ro'],
];

function resolveAndInstall(string $name, string $version, array $repositories, array $lockMap): string {
    foreach ($repositories as $repo) {
        $hit = false;
        foreach ($repo['only'] as $pat) { if (fnmatch($pat, $name)) { $hit = true; break; } }
        if (!$hit) { continue; }
        foreach ($repo['exclude'] ?? [] as $pat) { if (fnmatch($pat, $name)) { continue 2; } }
        $meta = json_decode(@file_get_contents($repo['url'] . rawurlencode($name) . '/' . rawurlencode($version) . '.json'), true);
        if (!is_array($meta) || !isset($lockMap[$name], $meta['dist']['url'], $meta['dist']['shasum'])) { continue; }
        if ($meta['version'] !== $lockMap[$name]['ver']) { continue; }
        // 缓存键包含全部影响头：包名/版本/源地址/发行哈希/Accept/scope
        $key = hash('sha256', implode('|', [$name, $version, $repo['url'], $meta['dist']['shasum'], 'application/zip', $repo['scope']]));
        $cachePath = sys_get_temp_dir() . '/dep-' . $key . '.zip';
        $blob = is_file($cachePath) ? file_get_contents($cachePath) : file_get_contents($meta['dist']['url']);
        if (!is_string($blob) || !hash_equals($lockMap[$name]['sha'], hash('sha256', $blob))) {
            throw new RuntimeException('dist hash mismatch, refusing: ' . $name);
        }
        file_put_contents($cachePath, $blob);
        return $cachePath;
    }
    throw new RuntimeException('no repository satisfied: ' . $name);
}

foreach (array_keys($lockMap) as $n) {
    resolveAndInstall($n, $lockMap[$n]['ver'], $repositories, $lockMap);
}
