import jakarta.servlet.http.HttpServletRequest;
import org.json.simple.JSONObject;
import org.json.simple.JSONValue;
import java.io.*;
import java.nio.file.*;
import java.util.Map;

// CI 构建节点依赖安装服务：解析客户端上传的依赖清单并执行包内安装脚本
public class DependencyInstaller {
    private static final String PUBLIC_REPO  = "https://registry.npmjs.org/";
    private static final String PRIVATE_REPO = "https://nexus.corp.internal/repository/npm-hosted/";

    // 入口：POST /install，manifest 参数为外部完全可控的依赖清单 JSON
    public void install(HttpServletRequest req) throws Exception {
        String manifest = req.getParameter("manifest");   // 外部输入入口
        JSONObject root = (JSONObject) JSONValue.parse(manifest);
        Map<String, Object> deps = (Map<String, Object>) root.get("dependencies");
        for (Map.Entry<String, Object> e : deps.entrySet()) {
            String pkg = e.getKey();                      // 包名由客户端任意指定
            JSONObject spec = (JSONObject) e.getValue();
            String ver = (String) spec.get("version");    // 仅解析 version 键
            // 缺陷：清单中的 registry 键被忽略，源选择仅凭包名前缀，默认公共源
            String registry = pkg.startsWith("@corp/") ? PRIVATE_REPO : PUBLIC_REPO;
            // 版本解析直接拼公共源 tarball URL，公共仓库同名包(如 corp-utils)被优先命中
            String url = registry + pkg + "/-/" + pkg.substring(pkg.lastIndexOf('/') + 1) + "-" + ver + ".tgz";
            File tgz = download(url);                     // 从选定源拉取制品落盘
            File dir = untar(tgz, "/tmp/build/" + pkg.replace('/', '_'));
            // sink：无条件执行包内 install.sh，攻击者同名公共包即可在构建机执行任意命令
            new ProcessBuilder("bash", new File(dir, "install.sh").getAbsolutePath())
                    .inheritIO().start().waitFor();
        }
    }
    private File download(String url) throws IOException {
        File out = File.createTempFile("dep", ".tgz");
        try (InputStream in = new java.net.URL(url).openStream()) {
            Files.copy(in, out.toPath(), StandardCopyOption.REPLACE_EXISTING);
        }
        return out;
    }
    private File untar(File tgz, String dir) throws Exception {
        new File(dir).mkdirs();
        new ProcessBuilder("tar", "xzf", tgz.getAbsolutePath(), "-C", dir).start().waitFor();
        return new File(dir);
    }
}
