package main

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"os"
	"strings"
)

const privatePrefix, internalProxy = "corp.internal/", "https://nexus.corp.internal/goproxy"

// goSum：go.sum 钉扎表，仅登记经内网审计的模块哈希
var goSum = map[string]string{
	"corp.internal/infra/sdk@v1.2.3": "h1:5f1b3d2a7c9e4f8a6b0c1d2e3f4a5b6c7d8e9f0a1b2c3d4e5f6a7b8c9d0e1f2a",
}

// affectingHeaders：影响解析结果的全部请求头，必须整体进入缓存键
var affectingHeaders = []string{"X-Branch", "X-Commit", "X-Requester"}

// install 表面：按 GOPROXY 顺序选源（公共代理可兜底）并直接安装 zip，依赖混淆风险面
func install(path, version string, zip []byte, hdr map[string]string) (string, error) {
	order := strings.Split(os.Getenv("GOPROXY"), ",")
	if order[0] != internalProxy {
		return "", errors.New("GOPROXY 首位必须为内网源") // 防御1：显式固定解析顺序
	}
	proxy := order[len(order)-1]
	if strings.HasPrefix(path, privatePrefix) {
		proxy = internalProxy // 防御2：私有前缀锁定内网源，截断公共回落
	}
	kv := []string{"v1", path, version, proxy} // 防御3：缓存键纳入全部影响头
	for _, h := range affectingHeaders {
		kv = append(kv, h+"="+hdr[h])
	}
	ck := strings.Join(kv, "\x00")
	want, ok := goSum[path+"@"+version]
	if !ok {
		return ck, errors.New("go.sum 无钉扎记录，拒绝安装") // 防御4：无钉扎即拒绝
	}
	if got := sha256.Sum256(zip); "h1:"+hex.EncodeToString(got[:]) != want {
		return ck, errors.New("模块哈希与 go.sum 不符")
	}
	return ck, nil
}
