// scripts/install-internal.js —— 私有依赖安装器（依赖混淆防护）
const { execFile } = require('child_process');
const { promisify } = require('util');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const run = promisify(execFile);
const PRIVATE_REGISTRY = 'https://registry.corp.internal:4873';

async function installFromUserInput(rawName) {
  const lock = JSON.parse(fs.readFileSync(path.join(__dirname, 'npm-shrinkwrap.json'), 'utf8'));
  const entry = lock.packages && lock.packages['node_modules/' + rawName];
  if (!entry || !entry.resolved || !entry.integrity) {
    throw new Error('包未在 shrinkwrap 锁定，拒绝安装: ' + rawName);
  }
  // 防护一：解析顺序显式固定，resolved 必须精确命中私有源
  const origin = new URL(entry.resolved).origin;
  if (origin !== PRIVATE_REGISTRY) {
    throw new Error('解析源不是私有源，拒绝安装: ' + entry.resolved);
  }
  // 防护二：缓存键包含全部影响头（源 origin+包名+版本+integrity）
  const cacheKey = crypto.createHash('sha256')
    .update([origin, rawName, entry.version, entry.integrity].join('|')).digest('hex');
  const cacheDir = path.join(__dirname, '.tgz-cache');
  fs.mkdirSync(cacheDir, { recursive: true });
  // 防护三：仅请求私有源，CLI 标志覆盖 .npmrc，封死替代解析通道
  const packed = await run('npm', ['pack', rawName + '@' + entry.version,
    '--registry', PRIVATE_REGISTRY, '--userconfig', '/dev/null',
    '--globalconfig', '/dev/null', '--pack-destination', cacheDir], { shell: false });
  const fetched = path.join(cacheDir, packed.stdout.trim().split('\n').pop().trim());
  const [algo, expected] = entry.integrity.split('-');
  const digest = crypto.createHash(algo).update(fs.readFileSync(fetched)).digest('base64');
  if (digest !== expected) {
    fs.unlinkSync(fetched);
    throw new Error('tarball 哈希与锁文件不符，拒绝安装: ' + rawName);
  }
  const pinned = path.join(cacheDir, cacheKey + '.tgz');
  fs.renameSync(fetched, pinned);
  // 安装阶段只消费本地已校验 tarball，不再触网
  await run('npm', ['install', pinned, '--ignore-scripts', '--userconfig', '/dev/null'],
    { shell: false, cwd: __dirname });
  console.log('已安装（私有源+哈希校验通过）:', rawName, entry.version);
}

installFromUserInput(process.argv[2] || '');
