// 显式固定解析顺序:私有前缀只走内部源,公共代理仅服务外部模块
const privatePrefix, privateProxy, publicProxy = "corp.internal/", "https://goproxy.corp.internal/", "https://proxy.golang.org/"

// goSum 模拟 go.sum 固定哈希库(占位示例值,非真实凭据)
