func fetchModule(w http.ResponseWriter, r *http.Request) {
	module := r.URL.Query().Get("module")
	version := r.URL.Query().Get("version")
	base := publicProxy
	if strings.HasPrefix(module, privatePrefix) {
		base = privateProxy // 私有源锁定:命中前缀绝不回退公共代理
	}
	pinned, ok := goSum[module+"@"+version]
	if !ok {
		http.Error(w, "unpinned version", http.StatusForbidden)
		return
	}
	// 缓存键包含全部影响头:端点+模块+版本,防跨源缓存投毒
	key := sha256.Sum256([]byte(base + "|" + module + "@" + version))
	resp, err := http.Get(base + module + "/@v/" + version + ".zip")
	if err != nil {
		http.Error(w, "fetch failed", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	data, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	sum := sha256.Sum256(data)
	if hex.EncodeToString(sum[:]) != pinned { // 哈希校验,替换包直接拒绝
		http.Error(w, "checksum mismatch", http.StatusForbidden)
		return
	}
	w.Write([]byte("verified"))
}
func main() { http.ListenAndServe("127.0.0.1:8080", http.HandlerFunc(fetchModule)) }
