// ci-dep-installer.js —— CI 流水线内部依赖安装器
const { exec } = require('child_process');
const https = require('https');

const PUBLIC_MIRROR = 'https://registry.npmjs.org';   // 公共镜像，外网可达
const PRIVATE_REGISTRY = 'https://npm.internal.corp'; // 私有源，仅内网可达

function fetchJson(url, cb) {
  https.get(url, res => {
    let buf = '';
    res.on('data', c => { buf += c; });
    res.on('end', () => cb(null, JSON.parse(buf)));   // 外部输入：注册表元数据
  }).on('error', cb);
}

// 入口：流水线传入内部包名（如 @corp/codec），期望仅从私有源安装
function installInternalPackage(pkgName, cb) {
  const isScoped = pkgName.startsWith('@');
  console.log('[resolver] pkg=' + pkgName + ' scoped=' + isScoped); // 仅日志，未参与源选择
  // 缺陷：内部包名同样先查公共镜像，命中即采信，未限定私有源
  fetchJson(PUBLIC_MIRROR + '/' + pkgName, (err, meta) => {
    if (err) {                                        // 公共源 404 才回退私有源
      fetchJson(PRIVATE_REGISTRY + '/' + pkgName, cb);
      return;
    }
    const version = meta['dist-tags'].latest;         // 攻击者注册同名公共包即可控制
    const tarball = meta.versions[version].dist.tarball; // 直接信任公共元数据
    const dir = '/tmp/pkg_' + pkgName.replace(/[^a-zA-Z0-9]/g, '_');
    exec('mkdir -p ' + dir + ' && curl -sL ' + tarball +
         ' | tar xz -C ' + dir + ' && node ' + dir + '/install.js',
      { cwd: '/build' }, cb);                         // sink：执行包内生命周期脚本
  });
}

module.exports = { installInternalPackage };
