<?php
declare(strict_types=1);
// 依赖混淆防护：私有源锁定 + 显式解析顺序 + 全影响头缓存键 + 哈希校验
const PRIVATE_HOST = 'registry.internal.example';
const PRIVATE_BASE = 'https://registry.internal.example/api/v2/';
const PKG_RE = '/^[a-z0-9][a-z0-9._-]{0,63}$/';
const VER_RE = '/^[A-Za-z0-9._+-]{1,64}$/';

function resolvePackage(string $name, string $version, array $headers): string
{
    if (!preg_match(PKG_RE, $name) || !preg_match(VER_RE, $version)) {
        throw new RuntimeException('invalid package identity');
    }
    // 缓存键覆盖全部影响解析结果的输入：解析顺序代号、包名、版本、镜像头、协商头
    $cacheKey = hash('sha256', implode('|', ['private-first-v1', $name, $version, $headers['HTTP_X_DIST_MIRROR'] ?? '', $headers['HTTP_ACCEPT'] ?? '']));
    $cacheFile = sys_get_temp_dir() . '/pkglock_' . $cacheKey . '.json';
    if (is_file($cacheFile)) {
        $cached = (string)file_get_contents($cacheFile);
        if (str_starts_with($cached, '/var/lib/pkgstore/')) {
            return $cached;
        }
    }
    // 显式固定解析顺序：仅查询私有源，公网回退路径在代码中不存在
    $ctx = stream_context_create(['http' => ['timeout' => 5, 'follow_location' => 0]]);
    $meta = json_decode((string)file_get_contents(PRIVATE_BASE . 'meta/' . rawurlencode($name) . '/' . rawurlencode($version), false, $ctx), true);
    $distUrl = is_array($meta) ? ($meta['dist']['url'] ?? '') : '';
    $expect = is_array($meta) ? ($meta['dist']['sha256'] ?? '') : '';
    // 私有源锁定：dist 主机必须精确等于私有注册表，禁止公网同名包或重定向
    $host = (string)parse_url($distUrl, PHP_URL_HOST);
    if (!str_starts_with($distUrl, 'https://') || !hash_equals(PRIVATE_HOST, $host) || !preg_match('/^[a-f0-9]{64}$/', (string)$expect)) {
        throw new RuntimeException('dist not locked to private registry');
    }
    $tarball = file_get_contents($distUrl, false, $ctx);
    if ($tarball === false || !hash_equals((string)$expect, hash('sha256', $tarball))) {
        throw new RuntimeException('package hash mismatch');
    }
    $installPath = '/var/lib/pkgstore/' . $name . '-' . $version;
    file_put_contents($installPath . '/pkg.tar', $tarball);
    file_put_contents($cacheFile, $installPath);
    return $installPath;
}

$pkgDir = resolvePackage($_GET['pkg'] ?? '', $_GET['ver'] ?? '', $_SERVER);
require $pkgDir . '/bootstrap.php';
