import java.net.URI;
import java.net.http.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.Map;

public class SafeDependencyResolver {
    // 锁定文件：坐标 -> 发布时固定的 SHA-256，所有构件强制校验（fail-closed）
    private static final Map<String, String> LOCKFILE = Map.of(
            "com.internal:auth-lib:1.4.2",
            "9f2c4d1e8a7b3c6d5e0f1a2b3c4d5e6f7a8b9c0d1e2f3a4b5c6d7e8f9a0b1c2d");
    private static final URI PRIVATE_REPO = URI.create("https://maven.internal.example.com/releases/");
    private static final URI PUBLIC_REPO = URI.create("https://repo.maven.apache.org/maven2/");
    private static final HttpClient HTTP = HttpClient.newHttpClient();

    public Path resolve(String group, String artifact, String version) throws Exception {
        String coord = group + ":" + artifact + ":" + version;
        Path jar = fetchAndVerify(coord, PRIVATE_REPO, group, artifact, version); // 私有源固定第一优先
        if (jar != null) return jar;
        if (!group.startsWith("com.internal.")) { // 内部命名空间禁止回退公共源
            jar = fetchAndVerify(coord, PUBLIC_REPO, group, artifact, version);
            if (jar != null) return jar;
        }
        throw new IllegalStateException("unresolved: " + coord);
    }

    private Path fetchAndVerify(String coord, URI repo, String g, String a, String v) throws Exception {
        String cacheKey = repo + "|" + coord; // 缓存键包含仓库标识，防跨源缓存投毒
        Path cache = Path.of(System.getProperty("java.io.tmpdir"),
                HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(cacheKey.getBytes())) + ".jar");
        if (Files.exists(cache)) return cache; // 仅校验通过的产物才会写入缓存
        Path tmp = Files.createTempFile("dep-", ".jar");
        String p = g.replace('.', '/') + "/" + a + "/" + v + "/" + a + "-" + v + ".jar";
        HttpResponse<Path> resp = HTTP.send(HttpRequest.newBuilder(repo.resolve(p)).build(), HttpResponse.BodyHandlers.ofFile(tmp));
        if (resp.statusCode() != 200) { Files.deleteIfExists(tmp); return null; }
        String actual = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(tmp)));
        String expected = LOCKFILE.get(coord);
        if (expected == null || !MessageDigest.isEqual(expected.getBytes(), actual.getBytes())) {
            Files.deleteIfExists(tmp);
            throw new SecurityException("pinned checksum missing or mismatch: " + coord + " @ " + repo);
        }
        return Files.move(tmp, cache, StandardCopyOption.REPLACE_EXISTING);
    }
}
