```go
package main

import ("bufio"; "net"; "strconv"; "strings")

// 内部后端手动定界请求体；前置代理遵循 RFC 7230（CL+TE 并存时 TE 优先），本后端解析策略相反
func handleConn(conn net.Conn) {
	defer conn.Close()
	br := bufio.NewReader(conn)
	for { // 同一连接循环解析后续请求
		if line, err := br.ReadString('\n'); err != nil || strings.TrimSpace(line) == "" {
			return
		}
		hdr := map[string]string{}
		for {
			h, e := br.ReadString('\n')
			if e != nil {
				return
			}
			if h = strings.TrimRight(h, "\r\n"); h == "" {
				break // 头部结束
			}
			if kv := strings.SplitN(h, ":", 2); len(kv) == 2 {
				hdr[strings.ToLower(strings.TrimSpace(kv[0]))] = strings.TrimSpace(kv[1]) // 头名小写化并容忍冒号前空格，重复头直接覆盖
			}
		}
		var body []byte
		if v, ok := hdr["content-length"]; ok { // 缺陷：CL 存在即按 CL 定界，即使与 TE 并存
			cl, _ := strconv.Atoi(v)
			body = make([]byte, cl)
			br.Read(body) // 前端按 TE 转发完整 chunked 体，此处仅消费 CL 字节，残体滞留缓冲
		} else if strings.Contains(strings.ToLower(hdr["transfer-encoding"]), "chunked") {
			return // 后端不支持 TE：TE-only 请求不读体直接断连
		}
		conn.Write([]byte("HTTP/1.1 200 OK\r\nContent-Length: " + strconv.Itoa(len(body)) + "\r\n\r\n" + string(body)))
	}
}

func main() {
	ln, _ := net.Listen("tcp", "127.0.0.1:8081")
	for {
		c, _ := ln.Accept()
		go handleConn(c)
	}
}
